function QuizQuestion({ q, selected, onSelect, revealed }) {
  const isCorrect = (i) => i === q.ans;
  return (
    <div className="bg-white/5 border border-white/10 rounded-2xl p-6 mb-5 backdrop-blur-md">
      <div className="flex items-start gap-3 mb-4" style={{ direction: "rtl" }}>
        <span className="bg-blue-500/20 border border-blue-400/30 text-blue-300 text-xs px-3 py-1 rounded-full flex-shrink-0 font-medium">
          {q.topic}
        </span>
        <p className="text-white font-bold text-base leading-relaxed flex-1">{q.id}. {q.q}</p>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {q.opts.map((opt, i) => {
          let cls = "rounded-xl border px-4 py-3.5 text-sm text-right cursor-pointer transition-all duration-200 w-full font-medium ";
          if (!revealed) {
            cls += selected === i
              ? "border-blue-400 bg-blue-500/20 text-white shadow-[0_0_15px_rgba(59,130,246,0.2)]"
              : "border-white/10 bg-white/5 text-blue-100 hover:border-blue-400/40 hover:bg-white/10";
          } else {
            if (isCorrect(i)) cls += "border-green-400 bg-green-500/20 text-green-200 font-bold";
            else if (selected === i && !isCorrect(i)) cls += "border-red-400 bg-red-500/20 text-red-200";
            else cls += "border-white/10 bg-white/5 text-blue-100/30 cursor-not-allowed";
          }
          return (
            <button key={i} className={cls} style={{ direction: "rtl" }} onClick={() => !revealed && onSelect(i)}>
              {opt}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function ScoreCard({ score, total, onClaim, isEligible }) {
  const pct = Math.round((score / total) * 100);
  const tier = getTier(pct);
  const conf = CERT_THRESHOLDS[tier];

  const tierStyles = {
    low: { border: "border-red-400/40", bg: "from-red-950/30 to-slate-900/30", badge: "text-red-300", glow: "#ef4444" },
    bronze: { border: "border-green-400/50", bg: "from-green-950/30 to-blue-950/30", badge: "text-green-300", glow: "#22c55e" },
    silver: { border: "border-blue-400/50", bg: "from-blue-950/30 to-indigo-950/30", badge: "text-blue-300", glow: "#3b82f6" },
    gold: { border: "border-yellow-400/60", bg: "from-yellow-950/30 to-amber-950/20", badge: "text-yellow-300", glow: "#eab308" },
  };
  const s = tierStyles[tier];

  return (
    <div className={`rounded-3xl border ${s.border} bg-gradient-to-br ${s.bg} p-8 text-center backdrop-blur-xl`}
      style={{ boxShadow: `0 0 40px ${s.glow}22` }}>
      <div className="text-7xl font-black mb-3" style={{ color: s.glow }}>{pct}%</div>
      <div className={`text-xl font-bold mb-2 ${s.badge}`}>
        {score} / {total} توغرا جاۋاب
      </div>
      <div className="h-px bg-white/10 my-6" />

      {!isEligible ? (
        <div className="text-amber-300 text-sm bg-amber-950/40 border border-amber-500/30 rounded-2xl p-5" style={{ direction: "rtl" }}>
          <div className="text-4xl mb-2">🔒</div>
          <p className="font-bold text-lg mb-1">گۇۋاھنامە قۇلۇپلانغان</p>
          <p className="text-amber-200/70 text-base">
            سوئاللارغا توغرا جاۋاب بەرگەن بولسىڭىزمۇ، لېكىن **بارلىق دەرس مودۇللىرى ۋە تاپشۇرۇقلارنى تولۇق ئورۇنداپ بولمىغانلىقىڭىز** ئۈچۈن گۇۋاھنامە ئېچىلمىدى. ئالدى بىلەن كۆرسەتكۈچلەرنى 100% قىلىڭ.
          </p>
        </div>
      ) : tier === "low" ? (
        <div className="text-red-300 text-sm" style={{ direction: "rtl" }}>
          <div className="text-4xl mb-3">😔</div>
          <p className="font-bold text-lg mb-1">ئۆتەلمىدىڭىز</p>
          <p className="text-red-200/70 text-base">گۇۋاھنامە تاقاقلىق. دەرىجىدىن ئۆتۈش ئۈچۈن كەم دېگەندە 70% نەتىجە كېرەك.</p>
        </div>
      ) : (
        <div style={{ direction: "rtl" }}>
          <div className="text-4xl mb-3">🎓</div>
          <p className={`font-black text-xl mb-4 ${s.badge}`}>
            {tier === "gold" ? "مۇبارەك بولسۇن! ئالتۇن دەرىجىلىك شەرەپكە ئېرىشتىڭىز!" :
              tier === "silver" ? "ئالاھىدە نەتىجە! كۈمۈش دەرىجىگە ئېرىشتىڭىز!" :
                "تەبرىكلەيمىز! مۇۋەپپەقىيەتلىك ئۆتتىڭىز!"}
          </p>
          <div className="space-y-3 mb-6">
            {conf.certs.map((c, i) => (
              <div key={i} className={`rounded-xl border px-4 py-3 text-base font-bold ${s.badge} ${s.border} bg-white/5 shadow-inner`}>
                🏅 {c}
              </div>
            ))}
          </div>
          <div className="space-y-3">
            {conf.certs.map((certType, i) => (
              <button
                key={i}
                onClick={() => onClaim(certType)}
                className={`w-full py-4 px-6 rounded-2xl font-black text-base transition-all duration-300 hover:scale-[102%] shadow-lg
                  ${tier === "gold"
                    ? "bg-gradient-to-r from-yellow-500 to-amber-400 text-black hover:from-yellow-400 hover:to-amber-300"
                    : tier === "silver"
                      ? "bg-gradient-to-r from-blue-500 to-indigo-500 text-white hover:from-blue-400 hover:to-indigo-400"
                      : "bg-gradient-to-r from-green-500 to-emerald-500 text-white hover:from-green-400 hover:to-emerald-400"
                  }`}
              >
                گۇۋاھنامىنى چۈشۈرۈش — {certType}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ── ئاساسىي چوڭ بىرىكمە (Main Component) ──────────────────────────────────────────────────────────────
export default function CyberPsychologyAndDigitalFuture() {
  const [tab, setTab] = useState("modules");
  const [completedModules, setCompletedModules] = useState({});
  const [completedAssignments, setCompletedAssignments] = useState({});
  const [answers, setAnswers] = useState({});
  const [quizSubmitted, setQuizSubmitted] = useState(false);
  const [quizScore, setQuizScore] = useState(null);
  const [animIn, setAnimIn] = useState(false);
  
  // ۋىدىئو ئۈچۈن قوشۇمچە تەرەققىياتلار
  const [activeVideo, setActiveVideo] = useState(null); 
  const videoRef = useRef(null);

  useEffect(() => {
    setTimeout(() => setAnimIn(true), 80);
  }, []);

  const modDone = Object.values(completedModules).filter(Boolean).length;
  const asgnDone = Object.values(completedAssignments).filter(Boolean).length;

  // بارلىق مودۇل ۋە تاپشۇرۇقلار ئورۇندالغانلىقىنى تەكشۈرۈش
  const isEverythingDone = modDone === MODULES.length && asgnDone === ASSIGNMENTS.length;

  const handleVideoProgress = () => {
    if (videoRef.current && activeVideo) {
      const { currentTime, duration } = videoRef.current;
      if (duration > 0) {
        const progressPercentage = (currentTime / duration) * 100;
        // ۋىدىئو 85 پىرسەنتكە يەتكەندە ئاپتوماتىك تاماملاش بەلگىسىنى ئۇرۇش
        if (progressPercentage >= 85 && !completedModules[activeVideo.modId]) {
          setCompletedModules((prev) => ({ ...prev, [activeVideo.modId]: true }));
        }
      }
    }
  };

  const handlePlayVideo = (modId, url) => {
    setActiveVideo({ modId, url });
  };

  const handleSubmitQuiz = () => {
    let score = 0;
    QUESTIONS.forEach((q) => {
      if (answers[q.id] === q.ans) score++;
    });
    setQuizScore(score);
    setQuizSubmitted(true);
    setTab("results");
  };

  const handleClaim = (certType) => {
    const pct = Math.round((quizScore / QUESTIONS.length) * 100);
    const params = new URLSearchParams({ score: pct, certType });
    window.location.href = `/certificate?${params.toString()}`;
  };

  const tabs = [
    { id: "modules", label: "دەرس مودۇللىرى", icon: "📚" },
    { id: "assignments", label: "تاپشۇرمىلار", icon: "📝" },
    { id: "quiz", label: "تەكشۈرۈش سوئاللىرى", icon: "🎯" },
    { id: "results", label: "نەتىجە", icon: "🏆" },
  ];

  return (
    <div className="min-h-screen text-white select-none relative overflow-x-hidden" style={{
      background: "linear-gradient(135deg, #020617 0%, #0f172a 50%, #020617 100%)",
      fontFamily: "'Segoe UI', 'Helvetica Neue', sans-serif",
    }}>
      {/* ئارقا كۆرۈنۈشتىكى ئېففېكتلار */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none z-0">
        <div className="absolute top-0 left-1/4 w-[600px] h-[600px] rounded-full opacity-[0.07] animate-pulse" style={{ background: "radial-gradient(circle, #3b82f6, transparent)", filter: "blur(120px)" }} />
        <div className="absolute bottom-1/4 right-1/4 w-[500px] h-[500px] rounded-full opacity-[0.05]" style={{ background: "radial-gradient(circle, #eab308, transparent)", filter: "blur(100px)" }} />
      </div>

      {/* ── يېڭىلانغان كۆركەم باش قىسىم (Hero Header) ────────────────────────────────────────────────── */}
      <header className={`relative pt-24 pb-16 px-4 z-10 transition-all duration-1000 ${animIn ? "opacity-100 translate-y-0" : "opacity-0 -translate-y-6"}`}>
        {/* ئارقا زىننەت توردىكى ئېففېكتى */}
        <div className="absolute inset-0 bg-[linear-gradient(to_right,#ffffff03_1px,transparent_1px),linear-gradient(to_bottom,#ffffff03_1px,transparent_1px)] bg-[size:4rem_4rem] [mask-image:radial-gradient(ellipse_60%_50%_at_50%_0%,#000_70%,transparent_100%)] pointer-events-none" />
        
        <div className="max-w-5xl mx-auto text-center relative z-10">
          <div className="inline-flex items-center gap-3 bg-slate-900/80 border border-yellow-500/30 rounded-full px-6 py-2.5 mb-8 backdrop-blur-xl shadow-2xl">
            <span className="text-yellow-400 text-sm animate-pulse">⬡</span>
            <span className="text-yellow-400 text-xs font-black tracking-widest uppercase">Uyghur AI Academy</span>
            <span className="text-yellow-400 text-sm animate-pulse">⬡</span>
          </div>

          <h1 className="text-4xl sm:text-6xl font-black leading-[1.3] mb-8" style={{ direction: "rtl" }}>
            <span className="bg-gradient-to-r from-white via-slate-100 to-blue-200 bg-clip-text text-transparent block pb-2">
              تور پسىخولوگىيەسى
            </span>
            <span className="bg-gradient-to-r from-yellow-400 via-amber-300 to-yellow-500 bg-clip-text text-transparent drop-shadow-lg block">
              ۋە ئۇيغۇر ئائىلىلىرىنىڭ رەقەملىك كەلگۈسى
            </span>
          </h1>

          <div className="flex justify-center mb-10">
            <p className="text-slate-300/80 text-base sm:text-lg max-w-3xl leading-loose bg-slate-900/40 border border-white/5 p-4 rounded-2xl backdrop-blur-md" style={{ direction: "rtl" }}>
              رەقەملىك سالاھىيەت • تور ئەخلاقى • بالىلار پسىخولوگىيەسى • سۈنئىي ئىدراك • كەلگۈسى ئەۋلاد تەربىيەسى
            </p>
          </div>

          {/* ئۈستۈنكى سىتاتىستىكا بارلىرى */}
          <div className="flex items-center justify-center gap-4 sm:gap-6 flex-wrap">
            {[
              { label: "دەرىسلىك مودۇلى", val: `${modDone}/${MODULES.length}`, color: "#3b82f6" },
              { label: "تاپشۇرما", val: `${asgnDone}/${ASSIGNMENTS.length}`, color: "#22c55e" },
              { label: "تەكشۈرۈش سوئالى", val: QUESTIONS.length, color: "#eab308" },
            ].map((s) => (
              <div key={s.label} className="flex items-center gap-4 bg-slate-900/60 border border-white/10 rounded-2xl px-6 py-3.5 shadow-xl backdrop-blur-md hover:border-white/20 transition-colors">
                <span className="font-black text-xl sm:text-2xl" style={{ color: s.color }}>{s.val}</span>
                <span className="text-slate-300 font-bold text-sm" style={{ direction: "rtl" }}>{s.label}</span>
              </div>
            ))}
          </div>

          {/* ئومۇمىي ئىلگىرىلەش بالدىقى */}
          <div className="max-w-md mx-auto mt-10 space-y-2.5 bg-slate-900/80 p-5 rounded-2xl border border-white/10 shadow-xl backdrop-blur-md">
            <div className="flex justify-between text-xs font-black text-slate-400 mb-1" style={{ direction: "rtl" }}>
              <span>ئومۇمىي ئۆگىنىش مۇساپىسى</span>
              <span className="text-yellow-400">{Math.round(((modDone + asgnDone) / (MODULES.length + ASSIGNMENTS.length)) * 100)}%</span>
            </div>
            <ProgressBar value={modDone + asgnDone} max={MODULES.length + ASSIGNMENTS.length} color="linear-gradient(90deg, #3b82f6, #22c55e, #eab308)" />
          </div>
        </div>
      </header>

      {/* يۆتكىلىشچان تىزىملىك (Sticky Navigation) */}
      <nav className="sticky top-0 z-40 border-b border-white/10 backdrop-blur-2xl bg-slate-950/80 shadow-xl">
        <div className="max-w-5xl mx-auto px-4 flex overflow-x-auto justify-start sm:justify-center">
          {tabs.map((t) => (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              className={`flex items-center gap-2 px-6 py-5 text-base font-bold border-b-2 transition-all whitespace-nowrap
                ${tab === t.id
                  ? "border-yellow-400 text-yellow-300 bg-white/5"
                  : "border-transparent text-slate-400 hover:text-slate-200"
                }`}
              style={{ direction: "rtl" }}
            >
              <span>{t.icon}</span>
              <span>{t.label}</span>
              {t.id === "modules" && <span className="bg-blue-500/20 text-blue-300 text-xs px-2 py-0.5 rounded-full ml-1">{modDone}</span>}
              {t.id === "assignments" && <span className="bg-green-500/20 text-green-300 text-xs px-2 py-0.5 rounded-full ml-1">{asgnDone}</span>}
            </button>
          ))}
        </div>
      </nav>

      {/* ئاساسىي مەزمۇن رايونى */}
      <main className="max-w-5xl mx-auto px-4 py-12 z-10 relative">
        {/* MODULES TAB */}
        {tab === "modules" && (
          <section className="animate-fadeIn">
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mb-8 border-b border-white/5 pb-4" style={{ direction: "rtl" }}>
              <div>
                <h2 className="text-2xl font-black text-white">ئاساسىي دەرىسلىك مودۇللىرى</h2>
                <p className="text-slate-400 text-sm mt-1">تۆۋەندىكى مودۇللارنى ئۆگىنىپ، ۋىدىئولارنى تولۇق كۆرۈپ چىقىڭ.</p>
              </div>
              <div className="w-full sm:w-48 bg-white/5 p-3 rounded-xl border border-white/5">
                <ProgressBar value={modDone} max={MODULES.length} color="#3b82f6" />
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {MODULES.map((m) => (
                <ModuleCard
                  key={m.id}
                  mod={m}
                  completed={!!completedModules[m.id]}
                  onToggle={() => setCompletedModules((p) => ({ ...p, [m.id]: !p[m.id] }))}
                  onPlayVideo={handlePlayVideo}
                />
              ))}
            </div>
          </section>
        )}

        {/* ASSIGNMENTS TAB */}
        {tab === "assignments" && (
          <section className="animate-fadeIn">
            <div className="mb-8 border-b border-white/5 pb-4" style={{ direction: "rtl" }}>
              <h2 className="text-2xl font-black text-white">ئەمەلىي تاپشۇرمىلار</h2>
              <p className="text-slate-400 text-sm mt-1">نەزەرىيەۋى بىلىملەرنى مۇستەھكەملەش ئۈچۈن تاپشۇرمىلارنى ئورۇنلاپ بەلگە قويۇڭ.</p>
            </div>
            <div className="space-y-4">
              {ASSIGNMENTS.map((a) => (
                <AssignmentCard
                  key={a.id}
                  asgn={a}
                  completed={!!completedAssignments[a.id]}
                  onToggle={() => setCompletedAssignments((p) => ({ ...p, [a.id]: !p[a.id] }))}
                />
              ))}
            </div>
          </section>
        )}

        {/* QUIZ TAB */}
        {tab === "quiz" && (
          <section className="animate-fadeIn">
            <div className="mb-8 border-b border-white/5 pb-4" style={{ direction: "rtl" }}>
              <h2 className="text-2xl font-black text-white">بىلىم تەكشۈرۈش سوئاللىرى</h2>
              <p className="text-slate-400 text-sm mt-1">
                جەمئىي {QUESTIONS.length} سوئالدىن <span className="text-yellow-400 font-bold">{Object.keys(answers).length}</span> سوئالغا جاۋاب بەردىڭىز.
              </p>
              <div className="mt-4 bg-white/5 p-3 rounded-xl border border-white/5 max-w-md">
                <ProgressBar value={Object.keys(answers).length} max={QUESTIONS.length} color="#eab308" />
              </div>
            </div>

            {QUESTIONS.map((q) => (
              <QuizQuestion
                key={q.id}
                q={q}
                selected={answers[q.id] ?? null}
                onSelect={(i) => setAnswers((p) => ({ ...p, [q.id]: i }))}
                revealed={quizSubmitted}
              />
            ))}

            {!quizSubmitted && (
              <div className="text-center mt-12">
                <button
                  onClick={handleSubmitQuiz}
                  disabled={Object.keys(answers).length < QUESTIONS.length}
                  className="px-12 py-4 rounded-2xl font-black text-base transition-all duration-300 hover:scale-105 disabled:opacity-30 disabled:cursor-not-allowed disabled:hover:scale-100 shadow-xl"
                  style={{
                    background: Object.keys(answers).length === QUESTIONS.length
                      ? "linear-gradient(135deg, #3b82f6, #6366f1)"
                      : "#1e293b",
                    boxShadow: Object.keys(answers).length === QUESTIONS.length ? "0 0 30px rgba(59,130,246,0.4)" : "none",
                  }}
                >
                  {Object.keys(answers).length < QUESTIONS.length
                    ? `يەنە ${QUESTIONS.length - Object.keys(answers).length} سوئال قالدى`
                    : "ئىمتىھاننى تاماملاپ، نەتىجىنى كۆرۈش ✓"}
                </button>
              </div>
            )}
          </section>
        )}

        {/* RESULTS TAB */}
        {tab === "results" && (
          <section className="max-w-xl mx-auto animate-fadeIn">
            <div className="mb-6 text-center" style={{ direction: "rtl" }}>
              <h2 className="text-2xl font-black text-white">نەتىجە ۋە ئاكادېمىيە گۇۋاھنامىسى</h2>
            </div>
            {quizScore === null ? (
              <div className="text-center text-slate-400 py-16 bg-white/5 rounded-3xl border border-white/10 backdrop-blur-md" style={{ direction: "rtl" }}>
                <div className="text-5xl mb-4 animate-bounce">🎯</div>
                <p className="text-lg font-semibold text-white">ئالدى بىلەن سوئاللارغا جاۋاب بېرىڭ</p>
                <p className="text-sm text-slate-400 mt-1 mb-6">گۇۋاھنامە سىستېمىسى قوزغىلىش ئۈچۈن سوئاللارنى تاماملىشىڭىز كېرەك.</p>
                <button
                  onClick={() => setTab("quiz")}
                  className="px-8 py-3 rounded-xl bg-blue-600 hover:bg-blue-500 text-white text-base font-bold transition-all shadow-md"
                >
                  سوئاللار رايونىغا ئۆتۈش
                </button>
              </div>
            ) : (
              <ScoreCard
                score={quizScore}
                total={QUESTIONS.length}
                onClaim={handleClaim}
                isEligible={isEverythingDone} // شەرت يەتكۈزۈش
              />
            )}
          </section>
        )}
      </main>

      {/* ── ۋىدىئو قويغۇچ كۆزنەكچىسى (Video Player Modal) ── */}
      {activeVideo && (
        <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4 backdrop-blur-md transition-all duration-300">
          <div className="bg-slate-900 border border-white/10 rounded-3xl overflow-hidden max-w-3xl w-full relative shadow-2xl">
            {/* يېپىش كۇنۇپكىسى */}
            <button 
              onClick={() => setActiveVideo(null)}
              className="absolute top-4 left-4 bg-black/60 hover:bg-black text-white w-9 h-9 rounded-full flex items-center justify-center font-bold text-sm z-10 border border-white/10 transition-colors"
            >
              ✕
            </button>
            {/* ۋىدىئو قويۇش رامكىسى */}
            <div className="aspect-video w-full bg-black">
              <video 
                ref={videoRef}
                src={activeVideo.url} 
                controls 
                autoPlay 
                onTimeUpdate={handleVideoProgress}
                className="w-full h-full object-contain"
              />
            </div>
          </div>
          {/* كۆزنەك سىرتى چىكىلسە يېپىلىش */}
          <div className="absolute inset-0 -z-10" onClick={() => setActiveVideo(null)} />
        </div>
      )}

      {/* تۆۋەنكى قىسىم (Footer) */}
      <footer className="border-t border-white/10 py-10 px-4 text-center mt-16 relative z-10 bg-slate-950/40 backdrop-blur-md">
        <div className="text-yellow-400 text-base font-black tracking-wider mb-2">UYGHUR AI ACADEMY</div>
        <div className="text-slate-500 text-sm font-medium" style={{ direction: "rtl" }}>
          © 2026 · بارلىق ھوقۇقلار ساقلانغان · رەقەملىك ئۇيغۇر كەلگۈسىنى بىرلىكتە قۇرايلى
        </div>
      </footer>
    </div>
  );
}