// src/pages/QuantumQuiz.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { quantumQuizData } from '../data/quantumQuiz';

export default function QuantumQuiz({ onQuizComplete }) {
  const navigate = useNavigate();

  // سىستېما ھالەتلىرى
  const [selectedLevel, setSelectedLevel] = useState(null); // 'beginner', 'intermediate', 'advanced'
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [score, setScore] = useState(0);
  const [showScore, setShowScore] = useState(false);
  
  // جاۋاب تاللاش ھالەتلىرى
  const [selectedOption, setSelectedOption] = useState(null);
  const [isAnswered, setIsAnswered] = useState(false);

  // ساقلانغان تارىخ بار-يوقلۇقىنى تەكشۈرۈش ھالىتى
  const [hasSavedProgress, setHasSavedProgress] = useState(false);
  const [savedLevelInfo, setSavedLevelInfo] = useState(null);

  // قوزغالغاندا ئوقۇغۇچىنىڭ ئىلگىرىكى توختىغان ئورنىنى تەكشۈرۈش
  useEffect(() => {
    const savedProgress = localStorage.getItem('quantum_quiz_progress');
    if (savedProgress) {
      const data = JSON.parse(savedProgress);
      setHasSavedProgress(true);
      setSavedLevelInfo(data);
    }
  }, []);

  // ئوقۇغۇچى سوئال ئىشلەۋاتقاندا ھەر بىر قەدەمنى ساقلاپ مېڭىش
  useEffect(() => {
    if (selectedLevel && !showScore) {
      const progressData = {
        level: selectedLevel,
        currentIdx: currentQuestionIdx,
        savedScore: score
      };
      localStorage.setItem('quantum_quiz_progress', JSON.stringify(progressData));
    }
  }, [selectedLevel, currentQuestionIdx, score, showScore]);

  // تاللانغان سەۋىيەدىكى سوئاللار تىزىملىكى
  const questions = selectedLevel ? quantumQuizData[selectedLevel] : [];
  const currentQuestion = questions[currentQuestionIdx];

  // يېڭىدىن باشتىن باشلاش
  const handleLevelSelect = (level) => {
    setSelectedLevel(level);
    setCurrentQuestionIdx(0);
    setScore(0);
    setShowScore(false);
    setIsAnswered(false);
    setSelectedOption(null);
    setHasSavedProgress(false);
  };

  // ئىلگىرى توختىغان ئورنىدىن داۋاملاشتۇرۇش
  const handleResumeProgress = () => {
    if (savedLevelInfo) {
      setSelectedLevel(savedLevelInfo.level);
      setCurrentQuestionIdx(savedLevelInfo.currentIdx);
      setScore(savedLevelInfo.savedScore);
      setShowScore(false);
      setIsAnswered(false);
      setSelectedOption(null);
      setHasSavedProgress(false);
    }
  };

  // تارىخنى ئۆچۈرۈۋېتىش
  const handleClearSavedProgress = () => {
    localStorage.removeItem('quantum_quiz_progress');
    setHasSavedProgress(false);
    setSavedLevelInfo(null);
  };

  // جاۋاب تاللىغاندا
  const handleOptionClick = (option) => {
    if (isAnswered) return;
    setSelectedOption(option);
    setIsAnswered(true);

    if (option === currentQuestion.answer) {
      setScore(prev => prev + 1);
    }
  };

  // كېيىنكى سوئالغا ئۆتۈش
  const handleNextClick = () => {
    const nextQuestion = currentQuestionIdx + 1;
    setIsAnswered(false);
    setSelectedOption(null);

    if (nextQuestion < questions.length) {
      setCurrentQuestionIdx(nextQuestion);
    } else {
      setShowScore(true);
      // سىناق تولۇق تۈگىگەندە ساقلانغان تارىخنى ئۆچۈرۈۋېتىمىز
      localStorage.removeItem('quantum_quiz_progress');
      
      if (onQuizComplete && score + (selectedOption === currentQuestion.answer ? 1 : 0) >= questions.length * 0.7) {
        onQuizComplete(); 
      }
    }
  };

  // ئوتتۇرىدىن چىكىنىپ باشلاش ئېكرانىغا قايتىش
  const handleExitToMenu = () => {
    if (window.confirm("سىناقنى يېرىم يولدا توختىتىپ باش تىزىملىككە قايتامسىز؟ (ئورنىڭىز ئاپتوماتىك ساقلىنىدۇ)")) {
      setSelectedLevel(null);
      // ئەگەر جەزملەشتۈرۈلۈپ چىقىپ كەتسە، كىرىش ئېكرانىدا داۋاملاشتۇرۇش كۇنۇپكىسى قوزغىلىدۇ
      const savedProgress = localStorage.getItem('quantum_quiz_progress');
      if (savedProgress) {
        setHasSavedProgress(true);
        setSavedLevelInfo(JSON.parse(savedProgress));
      }
    }
  };

  // ئىلگىرىلەش پىرسەنتى
  const progressPercent = questions.length > 0 ? ((currentQuestionIdx) / questions.length) * 100 : 0;

  return (
    <div className="p-6 max-w-3xl mx-auto min-h-screen text-right" dir="rtl">
      
      {/* 1. ئەڭ ئۈستۈنكى كۆركەم نېۋىگاتسىيە بالدىقى */}
      <div className="flex justify-between items-center bg-white dark:bg-slate-900 p-4 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 mb-8 gap-4" dir="ltr">
        <div className="flex gap-2">
          <button 
            onClick={() => navigate('/quantum-ai')} 
            className="px-4 py-2 bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-xl text-xs md:text-sm font-bold transition flex items-center gap-1"
          >
            🏠 باش بەت
          </button>
          <button 
            onClick={() => navigate('/quantum-lab')} 
            className="px-4 py-2 bg-indigo-50 text-indigo-600 hover:bg-indigo-100 dark:bg-indigo-950/50 dark:text-indigo-400 rounded-xl text-xs md:text-sm font-bold transition flex items-center gap-1"
          >
            🔬 كۋانت تەجرىبىخانا
          </button>
        </div>
        <span className="font-extrabold text-sm md:text-base bg-gradient-to-l from-indigo-500 to-purple-500 bg-clip-text text-transparent">
          ⚛️ كۋانت بىلىم سىناش سىستېمىسى
        </span>
      </div>

      {/* 2. ساقلانغان تارىخنى ئەسلىگە كەلتۈرۈش ئۇقتۇرۇشى */}
      {hasSavedProgress && !selectedLevel && (
        <div className="mb-6 p-4 bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-900/50 rounded-2xl flex flex-col md:flex-row justify-between items-center gap-4 animate-pulse">
          <div className="text-right">
            <h4 className="font-bold text-amber-800 dark:text-amber-400 text-sm">تۇياقسىز قالغان سىناق بايقالدى!</h4>
            <p className="text-xs text-amber-600 dark:text-amber-500 mt-0.5">
              سىز ئەڭ ئاخىرقى قېتىم <span className="font-bold">[{savedLevelInfo?.level === 'beginner' ? 'ئاساسىي' : savedLevelInfo?.level === 'intermediate' ? 'ئوتتۇرا' : 'يۇقىرى'}]</span> دەرىجىدىكى سىناقنىڭ {savedLevelInfo ? savedLevelInfo.currentIdx + 1 : 0}-سوئالىدا توختاپ قالغان ئىكەنسىز.
            </p>
          </div>
          <div className="flex gap-2" dir="ltr">
            <button onClick={handleClearSavedProgress} className="px-3 py-1.5 text-xs font-medium text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-950/30 rounded-lg transition">
              ئۆچۈرۈش ✕
            </button>
            <button onClick={handleResumeProgress} className="px-4 py-1.5 bg-amber-500 hover:bg-amber-600 text-white text-xs font-bold rounded-lg transition shadow-sm">
              شۇ يەردىن داۋاملاشتۇرۇش ➡️
            </button>
          </div>
        </div>
      )}

      {/* 3. سەۋىيە تاللاش بەتى */}
      {!selectedLevel ? (
        <div className="bg-white dark:bg-slate-900 rounded-3xl p-8 shadow-xl border border-slate-100 dark:border-slate-800 text-center">
          <div className="text-5xl mb-4">📝</div>
          <h2 className="text-2xl font-extrabold text-slate-900 dark:text-white mb-2">كۋانت سىناق دەرىجىسىنى تاللاڭ</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm mb-8">ئۆزىڭىزنىڭ كۋانت فىزىكىسى بىلىم سەۋىيەسىگە ماس كېلىدىغان تۈرنى تاللاپ يېڭىدىن باشلاڭ.</p>
          
          <div className="grid md:grid-cols-3 gap-4">
            <button onClick={() => handleLevelSelect('beginner')} className="p-6 rounded-2xl border-2 border-emerald-100 dark:border-emerald-950/50 bg-emerald-50/30 dark:bg-emerald-950/10 hover:border-emerald-500 transition-all text-center group">
              <div className="text-3xl mb-2 group-hover:scale-110 transition">🌱</div>
              <div className="font-bold text-emerald-600 dark:text-emerald-400">ئاساسىي دەرىجە</div>
              <div className="text-xs text-slate-400 mt-1">كۇبىت ۋە دەرۋازا ئاساسلىرى</div>
            </button>

            <button onClick={() => handleLevelSelect('intermediate')} className="p-6 rounded-2xl border-2 border-blue-100 dark:border-blue-950/50 bg-blue-50/30 dark:bg-blue-950/10 hover:border-blue-500 transition-all text-center group">
              <div className="text-3xl mb-2 group-hover:scale-110 transition">🔥</div>
              <div className="font-bold text-blue-600 dark:text-blue-400">ئوتتۇرا دەرىجە</div>
              <div className="text-xs text-slate-400 mt-1">ئالگورىزىملار ۋە ماشىنا ئۆگىنىشى</div>
            </button>

            <button onClick={() => handleLevelSelect('advanced')} className="p-6 rounded-2xl border-2 border-purple-100 dark:border-purple-950/50 bg-purple-50/30 dark:bg-purple-950/10 hover:border-purple-500 transition-all text-center group">
              <div className="text-3xl mb-2 group-hover:scale-110 transition">🚀</div>
              <div className="font-bold text-purple-600 dark:text-purple-400">يۇقىرى دەرىجە</div>
              <div className="text-xs text-slate-400 mt-1">خاتالىق تۈزىتىش ۋە ماتىرىسسا تەھلىلى</div>
            </button>
          </div>
        </div>
      ) : showScore ? (
        
        /* 4. نەتىجە كۆرسىتىش بەتى */
        <div className="bg-white dark:bg-slate-900 rounded-3xl p-10 shadow-xl border border-slate-100 dark:border-slate-800 text-center">
          <div className="text-6xl mb-6">🎉</div>
          <h2 className="text-3xl font-extrabold text-slate-950 dark:text-white">سىناق تاماممىلانمىدى!</h2>
          <p className="text-lg mt-4 text-slate-600 dark:text-slate-300">
            سىز جەمئىي <span className="font-bold text-indigo-600 dark:text-indigo-400">{questions.length}</span> سوئالدىن 
            <span className="font-bold text-emerald-500 mx-1">{score}</span> سىگە توغرا جاۋاب بەردىڭىز.
          </p>

          <div className="mt-4 max-w-md mx-auto bg-slate-50 dark:bg-slate-800/50 p-4 rounded-xl text-sm text-slate-500">
            توغرا جاۋاب بېرىش نىسبىتى: <span className="font-bold text-slate-800 dark:text-white">{Math.round((score / questions.length) * 100)}%</span>
          </div>

          {score >= questions.length * 0.7 ? (
            <p className="text-sm text-amber-500 mt-6 font-bold">🏆 قۇتۇقلۇقلايمىز! سىز يۇقىرى نەتىجە بىلەن ئۆتۈپ گۇۋاھنامە ئېلىش سالاھىيىتىگە ئېرىشتىڭىز.</p>
          ) : (
            <p className="text-sm text-rose-500 mt-6 font-bold">⚠️ گۇۋاھنامە ئېلىش ئۈچۈن كەم دېگەندە %70 نومۇر ئېلىشىڭىز كېرەك.</p>
          )}

          <div className="mt-8 flex justify-center gap-4">
            <button onClick={() => handleLevelSelect(selectedLevel)} className="px-6 py-3 bg-indigo-600 text-white font-bold rounded-xl text-sm hover:bg-indigo-700 transition">
              🔄 قايتا سىناش
            </button>
            <button onClick={() => setSelectedLevel(null)} className="px-6 py-3 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 font-bold rounded-xl text-sm hover:bg-slate-200 transition">
              🎛️ سەۋىيە ئالماشتۇرۇش
            </button>
          </div>
        </div>
      ) : (
        
        /* 5. ئاكتىپ سوئال-جاۋاب مەيدانى */
        <div className="bg-white dark:bg-slate-900 rounded-3xl p-6 md:p-8 shadow-xl border border-slate-100 dark:border-slate-800">
          
          {/* ئىلگىرىلەش بالدىقى */}
          <div className="w-full bg-slate-100 dark:bg-slate-800 h-2 rounded-full overflow-hidden mb-6" dir="ltr">
            <div 
              className="bg-gradient-to-r from-indigo-500 to-purple-500 h-full transition-all duration-300"
              style={{ width: `${progressPercent}%` }}
            ></div>
          </div>

          {/* سەۋىيە ئۇچۇرى ۋە يېرىم يولدا چېكىنىش كۇنۇپكىسى */}
          <div className="flex justify-between items-center mb-6">
            <span className="text-xs font-bold text-indigo-600 bg-indigo-50 dark:bg-indigo-950/60 dark:text-indigo-300 px-3 py-1 rounded-full">
              سوئال {currentQuestionIdx + 1} / {questions.length}
            </span>
            <div className="flex items-center gap-3">
              <span className="text-xs font-bold text-slate-400 uppercase">
                دەرىجە: {selectedLevel === 'beginner' ? 'ئاساسىي' : selectedLevel === 'intermediate' ? 'ئوتتۇرا' : 'يۇقىرى'}
              </span>
              <button 
                onClick={handleExitToMenu}
                className="px-2.5 py-1 text-xs font-semibold bg-rose-50 dark:bg-rose-950/40 text-rose-600 dark:text-rose-400 rounded-lg hover:bg-rose-100 transition"
              >
                🎛️ دەرىجە ئالماشتۇرۇش
              </button>
            </div>
          </div>

          <h2 className="text-xl font-extrabold text-slate-900 dark:text-white mb-6 leading-snug">
            {currentQuestion?.question}
          </h2>

          {/* تاللانمىلار كۇنۇپكىسى */}
          <div className="flex flex-col gap-3" dir="ltr">
            {currentQuestion?.options.map((option, idx) => {
              let btnStyle = "border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800 text-slate-800 dark:text-slate-200";
              
              if (isAnswered) {
                if (option === currentQuestion.answer) {
                  btnStyle = "border-emerald-500 bg-emerald-50 dark:bg-emerald-950/30 text-emerald-600 dark:text-emerald-400 font-bold";
                } else if (option === selectedOption) {
                  btnStyle = "border-rose-500 bg-rose-50 dark:bg-rose-950/30 text-rose-600 dark:text-rose-400";
                } else {
                  btnStyle = "opacity-50 border-slate-200 dark:border-slate-800 text-slate-400";
                }
              }

              return (
                <button
                  key={idx}
                  disabled={isAnswered}
                  onClick={() => handleOptionClick(option)}
                  className={`w-full text-right p-4 rounded-xl border transition-all text-sm md:text-base font-medium flex justify-between items-center gap-3 ${btnStyle}`}
                >
                  <span className="font-sans text-xs bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-md text-slate-400">{idx + 1}</span>
                  <span className="flex-1 text-right" dir="rtl">{option}</span>
                </button>
              );
            })}
          </div>

          {/* جاۋاب تەھلىلى ۋە مىسال چۈشەندۈرۈش */}
          {isAnswered && (
            <div className="mt-6 p-5 bg-indigo-50/50 dark:bg-slate-800/40 rounded-2xl border border-indigo-100/50 dark:border-slate-700/50 transition-all">
              <div className="flex items-center gap-2 mb-2">
                <span className="text-lg">{selectedOption === currentQuestion.answer ? '✅ توغرا جاۋاب!' : '❌ خاتا تاللاندى'}</span>
              </div>
              <p className="text-xs md:text-sm text-slate-600 dark:text-slate-300 leading-relaxed font-light">
                {currentQuestion.explanation}
              </p>
              
              <div className="mt-4 flex justify-end">
                <button
                  onClick={handleNextClick}
                  className="px-5 py-2.5 bg-slate-900 text-white dark:bg-white dark:text-slate-900 font-bold rounded-xl text-xs hover:opacity-90 transition shadow-md"
                >
                  {currentQuestionIdx + 1 === questions.length ? '🏁 نەتىجىنى كۆرۈش' : 'كېيىنكى سوئال ➡️'}
                </button>
              </div>
            </div>
          )}

        </div>
      )}
    </div>
  );
}