import React, { useState, useEffect, useContext } from 'react';
import { UserContext } from '../context/UserContext';
import { useLang } from '../context/LanguageContext';
import { useTheme } from '../context/ThemeContext';
import PostsModal from './PostsModal';
import PostCard from './PostCard';
import PostDetailModal from './PostDetailModal';

const Posts = () => {
  const { user } = useContext(UserContext);
  const { lang } = useLang();
  const { darkMode } = useTheme();
  
  const [showPostsModal, setShowPostsModal] = useState(false);
  const [showPostDetail, setShowPostDetail] = useState(false);
  const [selectedPost, setSelectedPost] = useState(null);
  const [posts, setPosts] = useState([]);
  const [editingPost, setEditingPost] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [showAdminPanel, setShowAdminPanel] = useState(false);

  // كاتېگورىيەلەر ئۇيغۇرچە ۋە ئىنگلىزچە تىل سىستېمىسىغا تولۇق ماسلاشتۇرۇلدى
  const categories = [
    { value: 'all', label: lang === 'ug' ? '🗂️ ھەممىسى' : 'All Categories' },
    { value: 'physics', label: lang === 'ug' ? '⚛️ فىزىكا' : 'Physics' },
    { value: 'mathematics', label: lang === 'ug' ? '🧮 ماتېماتىكا' : 'Mathematics' },
    { value: 'programming', label: lang === 'ug' ? '💻 پروگراممىلاش' : 'Programming' },
    { value: 'philosophy', label: lang === 'ug' ? '🏛️ پەلسەپە' : 'Philosophy' },
    { value: 'quantum', label: lang === 'ug' ? '🌌 كۋانت فىزىكىسى' : 'Quantum Physics' },
    { value: 'technology', label: lang === 'ug' ? '🚀 تېخنولوگىيە' : 'Technology' },
    { value: 'other', label: lang === 'ug' ? '📌 باشقىلار' : 'Other' }
  ];

  // يازمىلارنى يۈكلەش
  useEffect(() => {
    const savedPosts = JSON.parse(localStorage.getItem('posts')) || [];
    setPosts(savedPosts);
  }, []);

  // يېڭى يازما قوشۇش
  const handleNewPost = (newPost) => {
    const updatedPosts = [newPost, ...posts];
    setPosts(updatedPosts);
    localStorage.setItem('posts', JSON.stringify(updatedPosts));
  };

  // يازما ئۆزگەرتىش تارىخى بىلەن بىللە ساقلىنىدۇ
  const handleEditPost = (updatedPost) => {
    const updatedPosts = posts.map(post => 
      post.id === updatedPost.id 
        ? { 
            ...updatedPost, 
            editHistory: [
              ...(post.editHistory || []),
              {
                editedBy: user?.id,
                editedByName: user?.name,
                editedAt: new Date().toISOString(),
                previousContent: post.content,
                previousTitle: post.title
              }
            ]
          } 
        : post
    );
    setPosts(updatedPosts);
    localStorage.setItem('posts', JSON.stringify(updatedPosts));
    setEditingPost(null);
  };

  // يازما ئۆچۈرۈش مەشغۇلاتى ۋە خاتىرىسى
  const handleDeletePost = (postId) => {
    const postToDelete = posts.find(p => p.id === postId);
    const deletionRecord = {
      deletedBy: user?.id,
      deletedByName: user?.name,
      deletedAt: new Date().toISOString(),
      postTitle: postToDelete?.title,
      postAuthor: postToDelete?.authorName,
      postCategory: postToDelete?.category
    };

    const deletionHistory = JSON.parse(localStorage.getItem('postDeletionHistory')) || [];
    deletionHistory.push(deletionRecord);
    localStorage.setItem('postDeletionHistory', JSON.stringify(deletionHistory));

    const updatedPosts = posts.filter(post => post.id !== postId);
    setPosts(updatedPosts);
    localStorage.setItem('posts', JSON.stringify(updatedPosts));
    setShowPostDetail(false);
  };

  const handleDeleteCard = (postId) => {
    if (window.confirm(lang === 'ug' ? 'بۇ يازمىنى ئۆچۈرۈشنى جەزملەشتۈرەمسىز؟' : 'Are you sure you want to delete this post?')) {
      handleDeletePost(postId);
    }
  };

  // ياقتۇرۇش (Like) ئىقتىدارى
  const handleLike = (postId) => {
    const updatedPosts = posts.map(post => {
      if (post.id === postId) {
        const isLiked = post.likes?.includes(user?.id);
        return {
          ...post,
          likes: isLiked 
            ? post.likes.filter(id => id !== user?.id)
            : [...(post.likes || []), user?.id]
        };
      }
      return post;
    });
    setPosts(updatedPosts);
    localStorage.setItem('posts', JSON.stringify(updatedPosts));
  };

  // باھا (Comment) قوشۇش ئىقتىدارى
  const handleAddComment = (postId, comment) => {
    const updatedPosts = posts.map(post => {
      if (post.id === postId) {
        return {
          ...post,
          comments: [...(post.comments || []), {
            id: Date.now(),
            userId: user?.id,
            userName: user?.name || 'ئىشلەتكۈچى',
            text: comment,
            timestamp: new Date().toISOString()
          }]
        };
      }
      return post;
    });
    setPosts(updatedPosts);
    localStorage.setItem('posts', JSON.stringify(updatedPosts));
  };

  const handleSelectPost = (post) => {
    setSelectedPost(post);
    setShowPostDetail(true);
  };

  const handleEdit = (post) => {
    setEditingPost(post);
    setShowPostsModal(true);
  };

  // ئىزدەش ۋە كاتېگورىيە بويىچە سۈزۈش
  const filteredPosts = posts.filter(post => {
    const matchesSearch = post.title?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         post.content?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         post.authorName?.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesCategory = selectedCategory === 'all' || post.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  // 🛠️ باشقۇرغۇچى پانېلى زامانىۋى لايىھەدە (Admin Panel Component)
  const AdminPanel = () => {
    const [deletionHistory, setDeletionHistory] = useState([]);

    useEffect(() => {
      const history = JSON.parse(localStorage.getItem('postDeletionHistory')) || [];
      setDeletionHistory(history);
    }, []);

    const clearDeletionHistory = () => {
      if (window.confirm(lang === 'ug' ? 'تارىخنى پاكىز تازىلامسىز؟' : 'Clear all history?')) {
        localStorage.setItem('postDeletionHistory', JSON.stringify([]));
        setDeletionHistory([]);
      }
    };

    return (
      <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-md flex items-center justify-center p-4 z-50 transition-all duration-300">
        <div className={`rounded-2xl max-w-4xl w-full max-h-[90vh] overflow-y-auto shadow-2xl border transition-all transform duration-300 ${
          darkMode ? 'bg-slate-900 text-slate-100 border-slate-800' : 'bg-white text-slate-800 border-slate-100'
        }`}>
          <div className="p-6 sm:p-8">
            <div className="flex justify-between items-center mb-6 border-b pb-4 border-slate-100 dark:border-slate-800">
              <h2 className="text-2xl font-black flex items-center gap-2">
                ⚙️ {lang === 'ug' ? 'باشقۇرغۇچى كۆزنىكى' : 'Admin Operations'}
              </h2>
              <button
                onClick={() => setShowAdminPanel(false)}
                className="w-10 h-10 rounded-full flex items-center justify-center bg-slate-100 dark:bg-slate-800 hover:bg-rose-500 hover:text-white transition-all cursor-pointer font-bold text-lg"
              >
                ✕
              </button>
            </div>

            <div className="space-y-8">
              {/* ئىستاتىستىكا كارتىلىرى */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {[
                  { label: lang === 'ug' ? 'جەمئىي يازما' : 'Total Posts', value: posts.length, color: 'from-blue-500 to-blue-600', text: 'text-blue-500' },
                  { label: lang === 'ug' ? 'جەمئىي باھا' : 'Total Comments', value: posts.reduce((a, p) => a + (p.comments?.length || 0), 0), color: 'from-emerald-500 to-emerald-600', text: 'text-emerald-500' },
                  { label: lang === 'ug' ? 'ياقتۇرۇشلار' : 'Total Likes', value: posts.reduce((a, p) => a + (p.likes?.length || 0), 0), color: 'from-amber-500 to-amber-600', text: 'text-amber-500' },
                  { label: lang === 'ug' ? 'ئۆچۈرۈلگەن' : 'Deleted Log', value: deletionHistory.length, color: 'from-rose-500 to-rose-600', text: 'text-rose-500' }
                ].map((stat, i) => (
                  <div
                    key={i}
                    className={`p-5 rounded-2xl shadow-sm border text-center bg-gradient-to-br transition-all hover:shadow-md ${
                      darkMode ? 'bg-slate-950/40 border-slate-800' : 'bg-slate-50/60 border-slate-200'
                    }`}
                  >
                    <div className={`text-3xl font-black ${stat.text}`}>
                      {stat.value}
                    </div>
                    <div className="text-sm font-medium mt-1 opacity-80">
                      {stat.label}
                    </div>
                  </div>
                ))}
              </div>

              {/* ئۆچۈرۈش تارىخى جەدۋىلى */}
              <div className="rounded-2xl p-4 border border-slate-100 dark:border-slate-800 bg-slate-50/30 dark:bg-slate-950/20">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-bold flex items-center gap-1.5">
                    📋 {lang === 'ug' ? 'يازما ئۆچۈرۈش خاتىرىسى' : 'Deletion Logs History'}
                  </h3>
                  {deletionHistory.length > 0 && (
                    <button
                      onClick={clearDeletionHistory}
                      className="px-4 py-2 bg-rose-600 text-white rounded-xl text-sm font-bold hover:bg-rose-700 transition shadow-sm cursor-pointer"
                    >
                      {lang === 'ug' ? 'خاتىرىنى تازىلاش' : 'Clear History'}
                    </button>
                  )}
                </div>
                
                <div className="max-h-60 overflow-y-auto space-y-2 pr-1">
                  {deletionHistory.length > 0 ? (
                    deletionHistory.map((record, index) => (
                      <div
                        key={index}
                        className={`p-3.5 rounded-xl border transition-all ${
                          darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100 shadow-sm'
                        }`}
                      >
                        <div className="flex flex-col sm:flex-row justify-between gap-2">
                          <div>
                            <p className="font-bold text-base text-slate-800 dark:text-slate-200">{record.postTitle}</p>
                            <p className="text-xs opacity-70 mt-1">
                              {lang === 'ug' ? 'تۈرى' : 'Category'}: {record.postCategory || '—'} • {lang === 'ug' ? 'ئاپتور' : 'Author'}: {record.postAuthor || '—'}
                            </p>
                          </div>
                          <div className="text-right text-xs opacity-70 border-t sm:border-t-0 pt-2 sm:pt-0 border-slate-100 dark:border-slate-800">
                            <p>🗑️ {lang === 'ug' ? 'ئۆچۈرگۈچى' : 'Deleted by'}: <span className="font-bold text-rose-500">{record.deletedByName}</span></p>
                            <p className="mt-0.5" dir="ltr">{new Date(record.deletedAt).toLocaleString()}</p>
                          </div>
                        </div>
                      </div>
                    ))
                  ) : (
                    <p className="text-center py-8 opacity-60 text-base">
                      {lang === 'ug' ? 'ھېچقانداق ئۆچۈرۈش خاتىرىسى يوق' : 'No deletion history available.'}
                    </p>
                  )}
                </div>
              </div>

              {/* كاتېگورىيە سىستېمىلىق ئىستاتىستىكا */}
              <div>
                <h3 className="text-lg font-bold mb-4">
                  📊 {lang === 'ug' ? 'كاتېگورىيە بويىچە يازمىلار' : 'Posts Distribution By Category'}
                </h3>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                  {categories.filter(cat => cat.value !== 'all').map(category => {
                    const count = posts.filter(post => post.category === category.value).length;
                    return (
                      <div
                        key={category.value}
                        className={`p-4 rounded-xl text-center border transition-all ${
                          darkMode ? 'bg-slate-950/40 border-slate-800' : 'bg-slate-50 border-slate-100 shadow-sm'
                        }`}
                      >
                        <div className="font-black text-xl text-blue-500">{count}</div>
                        <div className="text-xs font-bold mt-1 opacity-80 truncate">
                          {category.label.split(' ')[1] || category.label}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  // 🎨 ئۇسلۇب لايىھە كىلاسلىرى تاللانمىسى
  const containerClass = darkMode ? 'bg-slate-950 text-slate-100 font-uyghur' : 'bg-slate-50 text-slate-800 font-uyghur';
  const inputClass = darkMode
    ? 'bg-slate-900 text-white border-slate-800 placeholder-slate-500 focus:border-blue-500 focus:ring-blue-500/20'
    : 'bg-white text-slate-800 border-slate-200 placeholder-slate-400 focus:border-blue-500 focus:ring-blue-500/20';

  return (
    <div className={`min-h-screen py-12 px-4 sm:px-6 lg:px-8 transition-colors duration-300 ${containerClass}`} dir={lang === 'ug' ? 'rtl' : 'ltr'}>
      <div className="max-w-7xl mx-auto">
        
        {/* ==================== باش قىسىم (Header) ==================== */}
        <div className="text-center mb-12">
          <div className="w-full flex justify-center mb-6">
            <img   
              src={`${process.env.PUBLIC_URL}/images/image05.png`} 
              alt="Logo"
              onError={(e) => { e.target.style.display = 'none'; }}
              className="w-28 sm:w-36 h-auto object-contain drop-shadow-xl"
            /> 
          </div>
          <h1 className="text-4xl sm:text-5xl font-black bg-gradient-to-r from-blue-600 via-indigo-500 to-purple-600 bg-clip-text text-transparent mb-4 tracking-wide">
            {lang === 'ug' ? 'ئىلىم-پەن يازمىلىرى' : 'Knowledge Shares'}
          </h1>
          <p className="text-lg sm:text-xl text-slate-500 dark:text-slate-400 max-w-2xl mx-auto font-medium">
            {lang === 'ug'
              ? 'ئەڭ يېڭى پەن-تېخنىكا، پروگراممىلاش ۋە ئەقلىي يازمىلار بىلەن تونۇشۇڭ'
              : 'Discover and share professional posts, tech trends, and scientific notes.'}
          </p>
        </div>

        {/* باشقۇرغۇچى پانېلى كۇنۇپكىسى */}
        {user?.role === 'admin' && (
          <div className="text-center mb-8">
            <button
              onClick={() => setShowAdminPanel(true)}
              className="bg-gradient-to-r from-rose-500 to-red-600 hover:from-rose-600 hover:to-red-700 text-white px-8 py-3 rounded-full font-bold shadow-lg shadow-rose-500/20 hover:shadow-rose-500/30 transition-all cursor-pointer transform hover:-translate-y-0.5 active:translate-y-0"
            >
              🔧 {lang === 'ug' ? 'باشقۇرغۇچى كۆزنىكىنى ئېچىش' : 'Open Admin Dashboard'}
            </button>
          </div>
        )}

        {/* ==================== ئىزدەش ۋە سۈزۈش تاختىسى ==================== */}
        <div className={`mb-8 p-6 rounded-2xl shadow-xl border transition-all duration-300 ${
          darkMode ? 'bg-slate-900/60 border-slate-800/80 backdrop-blur-md' : 'bg-white border-slate-100 shadow-slate-100/60'
        }`}>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-base font-bold mb-2 opacity-90">
                🔍 {lang === 'ug' ? 'ئىزدەش مەزمۇنى' : 'Search Keywords'}
              </label>
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder={lang === 'ug' ? 'تېما، مەزمۇن ياكى ئاپتور ئىسمى بويىچە ئىزدەڭ...' : 'Search by title, body, or author...'}
                className={`w-full px-4 py-3 rounded-xl border font-medium transition-all focus:outline-none focus:ring-4 ${inputClass}`}
              />
            </div>

            <div>
              <label className="block text-base font-bold mb-2 opacity-90">
                📁 {lang === 'ug' ? 'تۈر بويىچە سۈزۈش' : 'Filter by Category'}
              </label>
              <select
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value)}
                className={`w-full px-4 py-3 rounded-xl border font-medium transition-all focus:outline-none focus:ring-4 cursor-pointer ${inputClass}`}
              >
                {categories.map(category => (
                  <option key={category.value} value={category.value}>
                    {category.label}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="mt-4 flex flex-wrap justify-between items-center gap-3 pt-4 border-t border-slate-100/50 dark:border-slate-800/50">
            <span className="text-sm font-bold text-slate-500 dark:text-slate-400">
              📌 {lang === 'ug'
                ? `جەمئىي ${filteredPosts.length} يازما تېپىلدى`
                : `Found ${filteredPosts.length} posts matching criteria`}
            </span>
            {(searchQuery || selectedCategory !== 'all') && (
              <button
                onClick={() => {
                  setSearchQuery('');
                  setSelectedCategory('all');
                }}
                className="text-sm font-bold text-blue-600 dark:text-blue-400 hover:underline cursor-pointer"
              >
                🔄 {lang === 'ug' ? 'فىلترنى تازىلاش' : 'Reset Filters'}
              </button>
            )}
          </div>
        </div>

        {/* ==================== يازما يېزىش كۇنۇپكىسى ==================== */}
        {user && (
          <div className="text-center mb-12">
            <button
              onClick={() => {
                setEditingPost(null);
                setShowPostsModal(true);
              }}
              className="bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white px-10 py-4 rounded-xl font-black text-xl hover:shadow-xl hover:shadow-blue-500/20 transform hover:-translate-y-0.5 active:translate-y-0 transition-all duration-300 shadow-md cursor-pointer"
            >
              ✍️ {lang === 'ug' ? 'يېڭى يازما يوللاش' : 'Publish New Post'}
            </button>
          </div>
        )}

        {/* ==================== يازمىلار كۆرسىتىش رايونى ==================== */}
        {filteredPosts.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredPosts.map(post => (
              <PostCard
                key={post.id}
                post={post}
                onLike={handleLike}
                onComment={handleAddComment}
                onSelect={handleSelectPost}
                onEdit={user?.role === 'admin' || post.authorId === user?.id ? handleEdit : null}
                onDelete={user?.role === 'admin' || post.authorId === user?.id ? handleDeleteCard : null}
                currentUser={user}
                lang={lang}
                darkMode={darkMode}
              />
            ))}
          </div>
        ) : (
          <div className="text-center py-20 bg-white dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-inner">
            <div className="text-7xl mb-4 animate-bounce">🔍</div>
            <h3 className="text-2xl font-black text-slate-400 dark:text-slate-500 mb-2">
              {lang === 'ug' ? 'ھېچقانداق يازما تېپىلمىدى' : 'No posts matched your search'}
            </h3>
            <p className="text-slate-500 dark:text-slate-400 max-w-md mx-auto mb-6 text-base font-medium">
              {lang === 'ug'
                ? searchQuery || selectedCategory !== 'all'
                  ? 'باشقا ئىزدەش سۆزلىرىنى كىرگۈزۈپ سىناپ بېقىڭ ياكى فىلترنى ئۆزگەرتىڭ.'
                  : 'مۇنبىرىمىز تېخى قۇرۇق، تۇنجى يازمىنى سىز يوللاپ بېرىڭ!'
                : searchQuery || selectedCategory !== 'all'
                ? 'Try adapting your keyword search or switching back to all categories.'
                : 'Be the first pioneer to craft an amazing knowledge share here!'}
            </p>
            {user && (
              <button
                onClick={() => {
                  setEditingPost(null);
                  setShowPostsModal(true);
                }}
                className="bg-gradient-to-r from-blue-500 to-indigo-500 text-white px-6 py-2.5 rounded-xl font-bold hover:opacity-90 transition shadow-md cursor-pointer"
              >
                ✍️ {lang === 'ug' ? 'يازما يېزىش' : 'Write Now'}
              </button>
            )}
          </div>
        )}
      </div>

      {/* ==================== مودال كۆزنەكلەر (Modals) ==================== */}
      {showPostsModal && (
        <PostsModal
          post={editingPost}
          onClose={() => {
            setShowPostsModal(false);
            setEditingPost(null);
          }}
          onSuccess={editingPost ? handleEditPost : handleNewPost}
          isEditing={!!editingPost}
        />
      )}

      {showPostDetail && selectedPost && (
        <PostDetailModal
          post={selectedPost}
          onClose={() => setShowPostDetail(false)}
          onLike={handleLike}
          onComment={handleAddComment}
          onEdit={user?.role === 'admin' || selectedPost.authorId === user?.id ? handleEdit : null}
          onDelete={user?.role === 'admin' || selectedPost.authorId === user?.id ? handleDeletePost : null}
          currentUser={user}
        />
      )}

      {showAdminPanel && <AdminPanel />}
    </div>
  );
};

export default Posts;