import React from 'react';
import QuantumCircuitBuilder from '../components/quantum/QuantumCircuitBuilder';
import { useNavigate } from 'react-router-dom';

export default function QuantumLab() {
  const navigate = useNavigate();

  return (
    <div className="p-6 max-w-5xl mx-auto min-h-screen">
      <div className="flex flex-wrap justify-between items-center mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-extrabold text-slate-900 dark:text-white">کۋانت تەجرىبىخانىسى</h1>
          <p className="text-slate-500 dark:text-slate-400 mt-2">
            دەرۋازىلارنى چىكىش ئارقىلىق كۋانت ھالەت ئۆزگىرىشلىرىنى نەق مەيداندا كۆزىتىڭ.
          </p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => navigate('/quantum-ai')} className="px-4 py-2 bg-slate-200 dark:bg-slate-800 rounded-xl text-sm font-semibold">
            🏠 باش بەت
          </button>
          <button onClick={() => navigate('/quantum/quiz')} className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-sm font-semibold">
            📝 بىلىم سىناش
          </button>
        </div>
      </div>

      <QuantumCircuitBuilder />
    </div>
  );
}