import { useState, useEffect } from "react";
import courses from "../data/courses.json";
import { useNavigate } from "react-router-dom";
import { useTheme } from "../context/ThemeContext";
import { useAuth } from "../context/AuthContext";
import {
  FaLock, FaPlay, FaTag, FaAd, FaLockOpen,
  FaFileDownload, FaPaypal, FaCreditCard, FaCheck, FaCopy,
  FaBookOpen, FaUniversity,
  FaTimes, FaInfoCircle, FaLaptopCode
} from "react-icons/fa";

export default function Courses() {
  const [searchTerm, setSearchTerm] = useState("");
  const [sortBy, setSortBy] = useState("default");
  const [selectedCategory, setSelectedCategory] = useState("all");
  const [openAlbum, setOpenAlbum] = useState(null);

  // 💳 تۆلەش ھالەتلىرى
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState("paypal");
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [purchasedCourses, setPurchasedCourses] = useState(new Set());
  const [unlockedVideos, setUnlockedVideos] = useState(new Set());
  const [selectedCourse, setSelectedCourse] = useState(null);
  const [verificationCode, setVerificationCode] = useState("");
  const [generatedCode, setGeneratedCode] = useState("");
  const [copied, setCopied] = useState(false);

  // 🎬 ۋىدىئو ۋە تېما مەشىقخانا ھالەتلىرى
  const [activeVideo, setActiveVideo] = useState(null);
  const [selectedTopic, setSelectedTopic] = useState(null);
  const [userCode, setUserCode] = useState("");
  const [terminalOutput, setTerminalOutput] = useState("");

  // 🔍 تەپسىلاتى مودالى
  const [selectedDetailCourse, setSelectedDetailCourse] = useState(null);

  // 💳 كارتا ئۇچۇرلىرى
  const [cardInfo, setCardInfo] = useState({ number: "", expiry: "", cvc: "", name: "" });

  const navigate = useNavigate();
  const { darkMode } = useTheme();
  const { isLoggedIn, isAdmin } = useAuth();

  const allCategories = ["all", ...new Set(courses.map((c) => c.catigories || "General"))];

  useEffect(() => {
    const storedPurchased = localStorage.getItem("purchasedCourses");
    const storedUnlocked = localStorage.getItem("unlockedVideos");
    if (storedPurchased) setPurchasedCourses(new Set(JSON.parse(storedPurchased)));
    if (storedUnlocked) setUnlockedVideos(new Set(JSON.parse(storedUnlocked)));
  }, []);

  useEffect(() => {
    localStorage.setItem("purchasedCourses", JSON.stringify([...purchasedCourses]));
    localStorage.setItem("unlockedVideos", JSON.stringify([...unlockedVideos]));
  }, [purchasedCourses, unlockedVideos]);

  // 🔍 ئىزدەش ۋە سۈزۈش
  let filteredCourses = courses.filter((course) =>
    `${course.title} ${course.instructor}`
      .toLowerCase()
      .includes(searchTerm.toLowerCase())
  );
  if (selectedCategory !== "all") {
    filteredCourses = filteredCourses.filter(
      (course) => course.catigories === selectedCategory
    );
  }

  if (sortBy === "views") {
    filteredCourses.sort((a, b) => (b.views || 0) - (a.views || 0));
  } else if (sortBy === "likes") {
    filteredCourses.sort((a, b) => (b.likes || 0) - (a.likes || 0));
  } else if (sortBy === "duration") {
    filteredCourses.sort((a, b) => (parseInt(b.duration) || 0) - (parseInt(a.duration) || 0));
  }

  const isCoursePurchased = (courseId) => isAdmin || purchasedCourses.has(courseId);

  const isVideoUnlocked = (courseId, videoIndex) => {
    if (isCoursePurchased(courseId)) return true;
    if (videoIndex === 0) return true;
    return unlockedVideos.has(`${courseId}-${videoIndex}`);
  };

  const handlePurchaseCourse = (course) => {
    if (!isLoggedIn) {
      alert("ئالدى بىلەن سىستېمىغا كىرىڭ!");
      navigate("/login");
      return;
    }
    setSelectedCourse(course);
    setPaymentMethod("paypal");
    setShowPaymentModal(true);
  };

  const handleProcessPayment = () => {
    if (paymentMethod === "card" && (!cardInfo.number || !cardInfo.name || !cardInfo.expiry || !cardInfo.cvc)) {
      alert("كارتا ئۇچۇرلىرىنىڭ ھەممىسىنى تولدۇرۇڭ!");
      return;
    }
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setShowPaymentModal(false);
      const newCode = Math.random().toString(36).substring(2, 8).toUpperCase();
      setGeneratedCode(newCode);
      setShowSuccessModal(true);
    }, 1500);
  };

  const handleVerification = () => {
    if (verificationCode === generatedCode) {
      setPurchasedCourses(prev => new Set([...prev, selectedCourse.id]));
      setShowSuccessModal(false);
      setVerificationCode("");
      setGeneratedCode("");
      setCardInfo({ number: "", expiry: "", cvc: "", name: "" });
      alert('🎉 كورس مۇۋەپپەقىيەتلىك سېتىۋېلىندى! بارلىق ۋىدىيو ۋە مەشىقلەر ئېچىلدى.');
    } else {
      alert('❌ تەستىقلاش كودى خاتا! قايتا سىناڭ.');
    }
  };

  // 🤖 پايتون كود ئىجرا قىلىش تېرمىنالى
  const runPythonCode = () => {
    setTerminalOutput("⏳ كود سۈنئىي ئەقىل ئاكادېمىيىسى مۇلازىمېتىرىدا ئىجرا قىلىنىۋاتىدۇ...");
    setTimeout(() => {
      if (userCode.includes("import tensorflow") || userCode.includes("tf.data")) {
        setTerminalOutput("[KelBiL AI Engine] Environment: Python 3.10 + TensorFlow 2.x\n[INFO] Loaded dataset successfully.\n\n🚀 ئىجرا نەتىجىسى:\nMatrix Shape: (3, 2)\nتەقلىد قىلىش مۇۋەپپەقىيەتلىك بولدى، ھېچقانداق نۇقسان يوق!");
      } else if (userCode.includes("import numpy") || userCode.includes("np.array")) {
        setTerminalOutput("🚀 [Numpy Output]:\nMatrix successfully processed.\n[[1 2]\n [3 4]\n [5 6]]");
      } else if (userCode.includes("print")) {
        const matches = userCode.match(/print\((['"])(.*?)\1\)/);
        if (matches && matches[2]) {
          setTerminalOutput(`🚀 چىقىرىش نەتىجىسى:\n${matches[2]}`);
        } else {
          setTerminalOutput("🚀 چىقىرىش نەتىجىسى:\nكود نورمال ئىجرا قىلىندى.");
        }
      } else {
        setTerminalOutput("🚀 چىقىرىش نەتىجىسى:\nكود ئۇيغۇر سۈنئىي ئەقىل ئاكادېمىيىسىدە نورمال ئىجرا بولدى.");
      }
    }, 800);
  };

  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const getEmbedUrl = (url) => {
    if (!url) return "";
    let videoId = "";
    if (url.includes("youtube.com/watch")) {
      const urlParams = new URLSearchParams(new URL(url).search);
      videoId = urlParams.get("v");
    } else if (url.includes("youtu.be/")) {
      videoId = url.split("youtu.be/")[1]?.split(/[?#]/)[0];
    }
    return videoId ? `https://www.youtube.com/embed/${videoId}?autoplay=1` : url;
  };

  const currentOpenCourse = courses.find(a => a.id === openAlbum);

  // 💻 پايتون سانبۆلىكى قۇرۇلمىسى
  const renderPythonSandbox = () => (
    <div className="bg-gray-950 text-gray-100 rounded-3xl overflow-hidden shadow-2xl border border-gray-800" dir="ltr">
      <div className="p-4 bg-gray-900 border-b border-gray-800 flex justify-between items-center text-xs font-mono">
        <span className="text-emerald-400 flex items-center gap-1.5"><FaLaptopCode /> Kawuli AI Python Live Sandbox</span>
        <div className="flex items-center gap-1.5">
          <div className="w-2.5 h-2.5 rounded-full bg-red-500"></div>
          <div className="w-2.5 h-2.5 rounded-full bg-yellow-500"></div>
          <div className="w-2.5 h-2.5 rounded-full bg-green-500"></div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 h-[320px]">
        <div className="p-4 flex flex-col border-r border-gray-900">
          <label className="text-[11px] text-gray-500 font-mono mb-1">// PYTHON CODE INTERACTIVE SOURCE</label>
          <textarea
            value={userCode}
            onChange={(e) => setUserCode(e.target.value)}
            className="w-full flex-1 p-3 bg-gray-900 font-mono text-sm border border-gray-800 rounded-xl focus:outline-none focus:border-cyan-500 text-emerald-400 resize-none"
            spellCheck="false"
          />
          <button
            onClick={runPythonCode}
            className="mt-2 py-2.5 bg-gradient-to-r from-emerald-500 to-teal-600 text-white font-mono text-sm font-bold rounded-xl hover:from-emerald-600 transition"
          >
            ▶ RUN INTERACTIVE CODE (ئىجرا قىلىش)
          </button>
        </div>

        <div className="p-4 bg-black flex flex-col">
          <label className="text-[11px] text-gray-500 font-mono mb-1">// SYSTEM TERMINAL OUTPUT</label>
          <div className="flex-1 p-3 bg-gray-950 font-mono text-xs rounded-xl overflow-y-auto text-gray-300 whitespace-pre-wrap leading-relaxed border border-gray-900">
            {terminalOutput || "// نەتىجە بۇ يەردە كۆرۈنىدۇ..."}
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className={`p-4 sm:p-6 min-h-screen font-uyghur text-2xl transition-colors ${darkMode ? "bg-gray-900 text-white" : "bg-gray-50 text-gray-800"}`} dir="rtl">

      {/* 📢 ئەقلىي ئېلان سىستېمىسى */}
      <div className="bg-gradient-to-r from-cyan-700 to-amber-600 text-white p-4 rounded-2xl mb-6 flex items-center gap-3 max-w-6xl mx-auto shadow-lg text-xl font-bold">
        <FaAd className="text-2xl flex-shrink-0" />
        <span className="text-center flex-grow">
          🎉 يېڭى كورس: «كىۋانىت ماشىنا ئۆگىنىش» باشلاندى! ھازىر سېتىۋېلىش 20% ئىتبار!
        </span>
      </div>

      {/* 🏛 مەكتەپ دەرۋازىسى باش سۆزى */}
      <div className="mb-10 text-center py-12 bg-gradient-to-r from-slate-900 via-cyan-900 to-amber-800 rounded-3xl text-white shadow-2xl relative overflow-hidden">
        <h1 className="text-4xl sm:text-6xl font-black leading-relaxed px-4 tracking-wide text-transparent bg-clip-text bg-gradient-to-r from-white to-amber-300">
          ئۇيغۇر سۈنئىي ئەقىل ئاكادېمىيىسى
        </h1>
        <p className="mt-3 text-xl opacity-90 max-w-3xl mx-auto font-light">
          رەقەملىك دۇنيادىكى يۇقىرى تېخنىكا، كۈچلۈك پىروگرامما سىستېمىلىرى بىلىم مۇنبىرى
        </p>
      </div>

      {/* 🔍 ئىزدەش ۋە تەرتىپلەش تاختىسى */}
      <div className="max-w-6xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
        <input
          type="text"
          placeholder="ئاكادېمىيە دەرسلىكلىرى ياكى يېتەكچىلەرنى ئىزدەڭ..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="md:col-span-2 px-5 py-3.5 border rounded-2xl focus:ring-2 focus:ring-cyan-500 dark:bg-gray-800 dark:text-white dark:border-gray-700 shadow-inner text-xl"
        />
        <select
          value={sortBy}
          onChange={(e) => setSortBy(e.target.value)}
          className="px-5 py-3.5 border rounded-2xl dark:bg-gray-800 dark:text-white dark:border-gray-700 shadow-md text-xl font-bold"
        >
          <option value="default">🔢 سىستېمىلىق ئۆلچەم تەرتىپى</option>
          <option value="views">👁 ئەڭ كۆپ كۆرۈلگەنلەر</option>
          <option value="likes">❤️ ئەڭ كۆپ ئالقىشلانغانلار</option>
          <option value="duration">⏱ ئومۇمىي سائەت ئۇزۇنلۇقى</option>
        </select>
      </div>

      {/* 🗂 كاتېگورىيە تاختىسى */}
      <div className="max-w-6xl mx-auto flex flex-wrap gap-3 mb-8">
        {allCategories.map(cat => (
          <button
            key={cat}
            onClick={() => setSelectedCategory(cat)}
            className={`px-6 py-2.5 rounded-full text-lg font-bold transition duration-300 transform hover:scale-105 shadow-sm ${
              selectedCategory === cat ? "bg-gradient-to-r from-cyan-600 to-cyan-700 text-white shadow-xl" : "bg-white dark:bg-gray-800 text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700"
            }`}
          >
            {cat === "all" ? "🗂 بارلىق يۆنىلىشلەر" : `# ${cat}`}
          </button>
        ))}
      </div>

      {/* 🎓 ئاساسىي كۇرس تاختىلىرى كۆرۈنۈشى */}
      {!openAlbum ? (
        <>
          <div className="max-w-6xl mx-auto grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredCourses.map((course) => (
              <div
                key={course.id}
                className="bg-white dark:bg-gray-800 rounded-3xl overflow-hidden shadow-lg hover:shadow-2xl transition-all duration-300 border dark:border-gray-700 group flex flex-col justify-between"
              >
                <div className="relative aspect-video bg-slate-900 overflow-hidden cursor-pointer" onClick={() => setOpenAlbum(course.id)}>
                  <img src={course.image || "/images/course-placeholder.jpg"} alt={course.title} className="w-full h-full object-cover group-hover:scale-110 transition duration-500" />
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <div className="bg-cyan-600 text-white rounded-full p-4 shadow-2xl transform scale-75 group-hover:scale-100 transition duration-300">
                      <FaPlay className="text-xl translate-x-[-2px]" />
                    </div>
                  </div>
                  <div className="absolute top-4 left-4 bg-slate-900/80 backdrop-blur-md text-amber-400 text-sm px-3 py-1 rounded-full font-mono font-bold">
                    ¥ {course.price || "89.99"}
                  </div>
                  <div className="absolute bottom-4 right-4 bg-cyan-600 text-white text-xs px-3 py-1 rounded-full">
                    📚 {course.topics?.length || 0} تېما
                  </div>
                  {isCoursePurchased(course.id) && (
                    <div className="absolute top-4 right-4 bg-green-500/90 text-white text-xs px-3 py-1 rounded-full font-bold flex items-center gap-1">
                      <FaLockOpen /> سېتىۋېلىندى
                    </div>
                  )}
                </div>

                <div className="p-6 flex-grow flex flex-col justify-between">
                  <div>
                    <span className="text-xs font-bold text-cyan-600 dark:text-cyan-400 uppercase tracking-wider">{course.catigories || "General"}</span>
                    <h3 className="text-2xl font-bold my-2 text-gray-900 dark:text-white line-clamp-1 hover:text-cyan-600 cursor-pointer" onClick={() => setOpenAlbum(course.id)}>
                      {course.title}
                    </h3>
                    <p className="text-sm text-gray-500 dark:text-gray-400 line-clamp-2 mb-4">{course.description}</p>
                  </div>

                  <div className="space-y-4">
                    <div className="flex justify-between text-sm border-t pt-4 dark:border-gray-700 text-gray-400">
                      <span>👨‍🏫 {course.instructor}</span>
                      <span className="text-xs">⏱ {course.duration}</span>
                    </div>

                    <div className="grid grid-cols-2 gap-2">
                      {!isCoursePurchased(course.id) ? (
                        <button
                          onClick={() => handlePurchaseCourse(course)}
                          className="bg-gradient-to-r from-amber-500 to-amber-600 text-white text-sm py-2.5 rounded-xl font-bold shadow-md flex items-center justify-center gap-1 transition hover:from-amber-600 hover:to-amber-700"
                        >
                          <FaCreditCard /> سېتىۋېلىش
                        </button>
                      ) : (
                        <button
                          onClick={() => setOpenAlbum(course.id)}
                          className="bg-gradient-to-r from-green-500 to-emerald-600 text-white text-sm py-2.5 rounded-xl font-bold shadow-md flex items-center justify-center gap-1 transition"
                        >
                          <FaPlay /> كۆرۈش
                        </button>
                      )}

                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          setSelectedDetailCourse(course);
                        }}
                        className="bg-gray-100 dark:bg-gray-700 hover:bg-cyan-600 hover:text-white text-gray-700 dark:text-white text-sm py-2.5 rounded-xl font-bold transition flex items-center justify-center gap-1 z-10 relative"
                      >
                        <FaInfoCircle /> تەپسىلاتى
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {filteredCourses.length === 0 && (
            <div className="max-w-6xl mx-auto text-center mt-12 text-lg py-12 bg-white dark:bg-gray-800 rounded-3xl shadow-lg border dark:border-gray-700 text-gray-400">
              😕 ئىزدىگىنىڭىزگە ماس كۇرس تېپىلمىدى.
            </div>
          )}
        </>
      ) : (
        /* 🎬 تاللانغان دەرسنىڭ ئىچكى قىسمى */
        <div className="max-w-6xl mx-auto">
          <button onClick={() => { setOpenAlbum(null); setSelectedTopic(null); setActiveVideo(null); }} className="mb-6 px-5 py-2.5 bg-gray-600 hover:bg-gray-700 text-white rounded-xl flex items-center gap-2 transition shadow-md">
            🔙 بارلىق ئاكادېمىيە دەرسلىكلىرىگە قايتىش
          </button>

          <div className="bg-white dark:bg-gray-800 rounded-3xl p-6 shadow-xl mb-8 border dark:border-gray-700">
            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
              <div>
                <h2 className="text-3xl font-black text-cyan-600 dark:text-amber-400 mb-2">{currentOpenCourse?.title}</h2>
                <p className="text-gray-500 dark:text-gray-300 text-lg">{currentOpenCourse?.description}</p>
                <div className="flex flex-wrap gap-4 mt-4 text-sm text-gray-400">
                  <span>👨‍🏫 {currentOpenCourse?.instructor}</span>
                  <span>⏱ {currentOpenCourse?.duration}</span>
                  <span>📚 {currentOpenCourse?.topics?.length || 0} تېما</span>
                </div>
              </div>
              {!isCoursePurchased(openAlbum) ? (
                <button
                  onClick={() => handlePurchaseCourse(currentOpenCourse)}
                  className="bg-gradient-to-r from-amber-500 to-amber-600 text-white px-6 py-3 rounded-xl font-bold shadow-lg flex items-center justify-center gap-2 hover:from-amber-600 hover:to-amber-700 transition whitespace-nowrap"
                >
                  <FaCreditCard /> سېتىۋېلىش - ¥{currentOpenCourse?.price || "89.99"}
                </button>
              ) : (
                <span className="bg-green-500/10 text-green-500 px-6 py-3 rounded-xl font-bold flex items-center justify-center gap-2 whitespace-nowrap">
                  <FaLockOpen /> سېتىۋېلىندى - بارلىق ھوقۇق ئاچىلدى
                </span>
              )}
            </div>
          </div>

          {/* 📺 ۋىدىئو ۋە كود مەشىق رايونى */}
          {activeVideo && (
            <div className="mb-8 bg-white dark:bg-gray-800 rounded-3xl p-6 shadow-2xl border dark:border-gray-700 animate-fadeIn space-y-6">
              <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 border-b pb-4 dark:border-gray-700">
                <h3 className="text-2xl font-black text-red-500 flex items-center gap-2">
                  <span className="relative flex h-2.5 w-2.5">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-red-500"></span>
                  </span>
                  🎬 نەق مەيدان دەرسخانىسى: {activeVideo.title}
                </h3>
                <button
                  onClick={() => setActiveVideo(null)}
                  className="px-4 py-2 bg-gray-600 hover:bg-red-600 text-white rounded-xl text-sm font-bold flex items-center gap-1.5 transition whitespace-nowrap"
                >
                  <FaTimes /> ۋىدىئونى يېپىش
                </button>
              </div>

              <div className="aspect-video w-full bg-black rounded-2xl overflow-hidden shadow-inner border dark:border-gray-900">
                {activeVideo.src.includes("youtube.com") || activeVideo.src.includes("embed") || activeVideo.src.includes("youtu.be") ? (
                  <iframe
                    className="w-full h-full"
                    src={getEmbedUrl(activeVideo.src)}
                    title={activeVideo.title}
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                    allowFullScreen
                  ></iframe>
                ) : (
                  <video src={activeVideo.src} controls autoPlay className="w-full h-full"></video>
                )}
              </div>

              <div className="space-y-2">
                <div className="text-sm font-bold text-cyan-500">✍️ ۋىدىئونى كۆرگەچ مەشىق قىلىڭ:</div>
                {renderPythonSandbox()}
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* سول تەرەپ: تېمىلار مۇندەرىجىسى */}
            <div className="lg:col-span-1 space-y-3">
              <h3 className="text-xl font-bold text-gray-400 mb-3">📌 دەرسلىك تېمىلىرى</h3>
              {currentOpenCourse?.topics?.length > 0 ? currentOpenCourse.topics.map((topic, index) => {
                const unlocked = isVideoUnlocked(openAlbum, index);
                const isCurrentActive = selectedTopic?.id === topic.id || selectedTopic?.title === topic.title;
                return (
                  <div
                    key={topic.id || index}
                    onClick={() => {
                      if (unlocked) {
                        setSelectedTopic(topic);
                        setActiveVideo(null);
                        setUserCode(topic.code || "# كود تەمىنلەنمىگەن");
                        setTerminalOutput("💻 يېڭى تېما كودى تەييارلاندى. ئىجرا قىلىشنى بېسىڭ.");
                      } else {
                        alert("🔐 بۇ تېما قۇلۇپلانغان. ئالدى بىلەن دەرسنى سېتىۋېلىڭ.");
                      }
                    }}
                    className={`p-4 rounded-2xl border cursor-pointer transition-all ${
                      isCurrentActive
                        ? "bg-cyan-600 text-white border-cyan-600 shadow-md transform scale-[1.02]"
                        : unlocked
                          ? "bg-white dark:bg-gray-800 hover:bg-gray-100 dark:hover:bg-gray-700 border-gray-200 dark:border-gray-700"
                          : "bg-gray-200/50 dark:bg-gray-900/40 border-dashed opacity-50 cursor-not-allowed"
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <span className="text-xs font-mono px-2 py-0.5 rounded bg-black/10">تېما {index + 1}</span>
                        <h4 className="font-bold text-base truncate max-w-[160px]">{topic.title}</h4>
                      </div>
                      <div className="text-sm">
                        {unlocked ? <FaLockOpen className="text-green-500" /> : <FaLock className="text-amber-500" />}
                      </div>
                    </div>
                  </div>
                );
              }) : (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl text-center text-gray-400 border dark:border-gray-700">
                  بۇ كۇرستا تېخى تېما قوشۇلمىدى.
                </div>
              )}
            </div>

            {/* ئوڭ تەرەپ: تاللانغان تېما تەپسىلاتى */}
            <div className="lg:col-span-2 space-y-6">
              {selectedTopic ? (
                <div className="space-y-6 animate-fadeIn">
                  <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-md border dark:border-gray-700">
                    <div className="flex flex-col sm:flex-row justify-between items-start gap-3 mb-3">
                      <h3 className="text-2xl font-black text-cyan-600 dark:text-amber-400">📖 تېما مەزمۇنى: {selectedTopic.title}</h3>
                      <button
                        onClick={() => setActiveVideo({ title: selectedTopic.title, src: selectedTopic.youtubeUrl || currentOpenCourse?.fullYoutubeUrl || "https://www.w3schools.com/html/mov_bbb.mp4" })}
                        className="px-5 py-2 bg-gradient-to-r from-red-500 to-red-600 text-white rounded-xl text-sm font-bold flex items-center gap-1.5 hover:from-red-600 transition shadow-lg transform hover:scale-105 whitespace-nowrap"
                      >
                        <FaPlay /> ۋىدىئونى قويۇش
                      </button>
                    </div>
                    <p className="text-lg text-gray-700 dark:text-gray-300 leading-relaxed mb-4">{selectedTopic.description}</p>

                    {selectedTopic.code_description && (
                      <div className="p-3.5 bg-cyan-500/5 rounded-xl border border-cyan-500/20 text-sm text-gray-400 flex items-start gap-2 mb-3">
                        <FaInfoCircle className="text-cyan-500 mt-1 flex-shrink-0" />
                        <span><strong>كود بايانى:</strong> {selectedTopic.code_description}</span>
                      </div>
                    )}

                    <div className="pt-3 border-t dark:border-gray-700 flex justify-between items-center text-sm">
                      <span className="text-gray-400">📂 شۇ تېمىغا ئائىت مەنبە بايلىق:</span>
                      <button
                        onClick={() => alert(`💾 [${selectedTopic.title}] تېمىسىغا ئائىت پايتون كود مەنبە ھۆججىتى مۇۋەپپەقىيەتلىك چۈشۈرۈلدى.`)}
                        className="px-3 py-1 bg-gradient-to-r from-cyan-600 to-teal-600 text-white rounded-xl text-xs font-bold flex items-center gap-1"
                      >
                        <FaFileDownload /> ئەسلى كود ھۆججىتىنى يۈكلەش
                      </button>
                    </div>
                  </div>

                  {!activeVideo && (
                    <div className="space-y-2">
                      <div className="text-sm font-bold text-gray-400">💻 تېما پايتون مەشىق مەيدانى:</div>
                      {renderPythonSandbox()}
                    </div>
                  )}
                </div>
              ) : (
                <div className="bg-white dark:bg-gray-800 p-12 rounded-3xl text-center border border-dashed border-gray-300 dark:border-gray-700 text-gray-400">
                  <FaLaptopCode className="text-5xl mx-auto mb-4 text-cyan-600/50" />
                  <p>سول تەرەپتىكى تېمىلاردىن بىرىنى چەكسىڭىز، تەپسىلىي مەزمۇنى، كودى ۋە ۋىدىئونى تەڭ كۆرۈش تاختىسى دەرھال ئېچىلىدۇ.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* 🔍 دەرس ئومۇمىي مۇندەرىجە تەپسىلات مودالى */}
      {selectedDetailCourse && (
        <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-[999] p-4 backdrop-blur-md animate-fadeIn">
          <div className="bg-white dark:bg-gray-800 rounded-3xl w-full max-w-2xl p-6 shadow-2xl relative border dark:border-gray-700 text-right max-h-[90vh] overflow-y-auto">
            <button
              onClick={() => setSelectedDetailCourse(null)}
              className="absolute top-4 left-4 text-gray-400 hover:text-gray-600 dark:hover:text-white text-xl"
            >
              <FaTimes />
            </button>
            <h3 className="text-2xl font-black text-cyan-600 dark:text-amber-400 mb-4 flex items-center gap-2">
              <FaBookOpen /> كۇرس ئومۇمىي قۇرۇلمىسى ۋە مۇندەرىجىسى
            </h3>
            <div className="space-y-3 font-medium text-lg text-gray-700 dark:text-gray-200">
              <p><strong>كۇرس نامى:</strong> {selectedDetailCourse.title}</p>
              <p><strong>يېتەكچى ئوقۇتقۇچى:</strong> {selectedDetailCourse.instructor}</p>
              <p><strong>ئومۇمىي سائەت ۋاقتى:</strong> {selectedDetailCourse.duration}</p>
              <p><strong>باھاسى:</strong> {selectedDetailCourse.price || "89.99"} ¥</p>
              <p className="text-gray-500 dark:text-gray-400">{selectedDetailCourse.description}</p>

              <div className="border-t pt-3 mt-3 dark:border-gray-700">
                <strong className="text-cyan-600 dark:text-cyan-400">📌 بارلىق تېمىلار تىزىملىكى:</strong>
                <div className="max-h-48 overflow-y-auto mt-2 space-y-1.5 pr-2" dir="rtl">
                  {selectedDetailCourse.topics?.length > 0 ? selectedDetailCourse.topics.map((t, idx) => (
                    <div key={idx} className="bg-gray-50 dark:bg-gray-900 p-2.5 rounded-xl text-base flex items-center gap-2 border dark:border-gray-700">
                      <span className="bg-cyan-600 text-white text-xs px-2 py-0.5 rounded font-mono">{idx + 1}</span>
                      <span className="truncate font-bold">{t.title}</span>
                    </div>
                  )) : (
                    <p className="text-gray-400 text-sm">تېما تىزىملىكى تېخى قوشۇلمىدى.</p>
                  )}
                </div>
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              {!isCoursePurchased(selectedDetailCourse.id) && (
                <button
                  onClick={() => {
                    setSelectedDetailCourse(null);
                    handlePurchaseCourse(selectedDetailCourse);
                  }}
                  className="flex-1 bg-gradient-to-r from-amber-500 to-amber-600 text-white py-3 rounded-xl font-bold shadow-md flex items-center justify-center gap-2"
                >
                  <FaCreditCard /> سېتىۋېلىش
                </button>
              )}
              <button
                onClick={() => {
                  setSelectedDetailCourse(null);
                  setOpenAlbum(selectedDetailCourse.id);
                }}
                className="flex-1 bg-cyan-600 hover:bg-cyan-700 text-white py-3 rounded-xl font-bold shadow-md transition"
              >
                دەرسكە كىرىش
              </button>
            </div>
            <button
              onClick={() => setSelectedDetailCourse(null)}
              className="w-full mt-3 bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-white py-3 rounded-xl font-bold"
            >
              ياپىمەن
            </button>
          </div>
        </div>
      )}

      {/* 💳 تۆلەش ئۆتكىلى مودالى */}
      {showPaymentModal && selectedCourse && (
        <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl w-full max-w-2xl shadow-2xl text-right max-h-[90vh] overflow-y-auto">
            <h3 className="text-2xl font-black mb-2 text-center text-cyan-600 dark:text-amber-400">💳 بىخەتەر ئاكادېمىك تۆلەش ئۆتكىلى</h3>
            <p className="text-center text-gray-400 text-sm mb-6">
              {selectedCourse.title} — ¥{selectedCourse.price || "89.99"}
            </p>

            <div className="grid grid-cols-3 gap-3 mb-6 font-bold text-sm">
              <button onClick={() => setPaymentMethod("paypal")} className={`p-3 border rounded-xl flex flex-col items-center gap-2 transition ${paymentMethod === "paypal" ? "border-cyan-500 bg-cyan-500/10 text-cyan-500" : "border-gray-300 dark:border-gray-700 text-gray-500"}`}><FaPaypal className="text-2xl" /> PayPal</button>
              <button onClick={() => setPaymentMethod("card")} className={`p-3 border rounded-xl flex flex-col items-center gap-2 transition ${paymentMethod === "card" ? "border-purple-500 bg-purple-500/10 text-purple-500" : "border-gray-300 dark:border-gray-700 text-gray-500"}`}><FaCreditCard className="text-2xl" /> Visa / Card</button>
              <button onClick={() => setPaymentMethod("iban")} className={`p-3 border rounded-xl flex flex-col items-center gap-2 transition ${paymentMethod === "iban" ? "border-amber-500 bg-amber-500/10 text-amber-500" : "border-gray-300 dark:border-gray-700 text-gray-500"}`}><FaUniversity className="text-2xl" /> IBAN / بانكا</button>
            </div>

            <div className="bg-gray-50 dark:bg-gray-900/50 p-4 rounded-2xl mb-6 border dark:border-gray-700">
              {paymentMethod === "paypal" && (
                <div className="text-center space-y-3">
                  <p className="text-sm text-gray-400">تۆۋەندىكى ئورگان پەيپال ئادرېسىغا مەبلەغ يوللاڭ:</p>
                  <div className="flex items-center justify-center gap-2">
                    <p className="font-mono text-xl font-bold text-cyan-600">academy@kelbil.edu</p>
                    <button
                      onClick={() => copyToClipboard('academy@kelbil.edu')}
                      className="px-2 py-1.5 bg-cyan-600 text-white rounded-lg hover:bg-cyan-700 transition text-xs flex items-center gap-1"
                    >
                      {copied ? <FaCheck /> : <FaCopy />}
                    </button>
                  </div>
                  <p className="text-xs text-gray-400">مەبلەغ يوللاپ بولغاندىن كېيىن "تۆلەپ بولدۇم" كۇنۇپكىسىنى بېسىڭ.</p>
                </div>
              )}
              {paymentMethod === "card" && (
                <div className="space-y-3 font-mono text-left" dir="ltr">
                  <input type="text" placeholder="Cardholder Name" value={cardInfo.name} onChange={e => setCardInfo({...cardInfo, name: e.target.value})} className="w-full p-2.5 border rounded-lg bg-transparent dark:border-gray-700 text-sm dark:text-white" />
                  <input type="text" placeholder="Card Number (4242 4242 4242 4242)" maxLength={19} value={cardInfo.number} onChange={e => setCardInfo({...cardInfo, number: e.target.value})} className="w-full p-2.5 border rounded-lg bg-transparent dark:border-gray-700 text-sm dark:text-white" />
                  <div className="flex gap-2">
                    <input type="text" placeholder="MM/YY" maxLength={5} value={cardInfo.expiry} onChange={e => setCardInfo({...cardInfo, expiry: e.target.value})} className="w-1/2 p-2.5 border rounded-lg bg-transparent dark:border-gray-700 text-sm dark:text-white" />
                    <input type="text" placeholder="CVC" maxLength={4} value={cardInfo.cvc} onChange={e => setCardInfo({...cardInfo, cvc: e.target.value})} className="w-1/2 p-2.5 border rounded-lg bg-transparent dark:border-gray-700 text-sm dark:text-white" />
                  </div>
                </div>
              )}
              {paymentMethod === "iban" && (
                <div className="space-y-2 text-sm text-left font-mono" dir="ltr">
                  <div className="bg-white dark:bg-gray-800 p-3 rounded-xl border dark:border-gray-700 text-xs flex items-center justify-between">
                    <div><strong>IBAN:</strong> DE89 5001 0517 2234 5678 00</div>
                    <button
                      onClick={() => copyToClipboard('DE89500105172234567800')}
                      className="px-2 py-1 bg-amber-500 text-white rounded-lg hover:bg-amber-600 transition flex items-center gap-1"
                    >
                      {copied ? <FaCheck /> : <FaCopy />}
                    </button>
                  </div>
                  <div className="bg-white dark:bg-gray-800 p-3 rounded-xl border dark:border-gray-700 text-xs">
                    <div><strong>Beneficiary:</strong> KelBiL Academy</div>
                  </div>
                  <p className="text-gray-400 text-xs" dir="rtl">يۇقىرىدىكى IBAN غا چىقىمنى يوللاپ، "تۆلەپ بولدۇم" نى بېسىڭ.</p>
                </div>
              )}
            </div>

            <div className="flex gap-3">
              <button onClick={handleProcessPayment} disabled={isLoading} className="flex-1 py-3 bg-green-600 hover:bg-green-700 text-white rounded-xl font-bold transition disabled:opacity-50">{isLoading ? "🔄 تەكشۈرۈۋاتىدۇ..." : "تۆلەپ بولدۇم"}</button>
              <button onClick={() => setShowPaymentModal(false)} className="flex-1 py-3 bg-gray-700 hover:bg-gray-800 text-white rounded-xl font-medium transition">ياپىمەن</button>
            </div>
          </div>
        </div>
      )}

      {/* ✅ جەزملەش كود مودالى */}
      {showSuccessModal && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl w-full max-w-md shadow-2xl text-center">
            <div className="w-16 h-16 bg-green-500 text-white rounded-full flex items-center justify-center mx-auto mb-4 text-2xl"><FaCheck /></div>
            <h3 className="text-xl font-bold mb-2 dark:text-white">تەستىقلاش كودى</h3>
            <p className="text-sm text-gray-400 mb-3">تۆۋەندىكى كودنى كىرگۈزۈپ تەستىقلاڭ:</p>
            <div className="bg-gray-100 dark:bg-gray-900 p-3 rounded-xl mb-4 font-mono text-2xl font-bold text-green-500">{generatedCode}</div>
            <input type="text" value={verificationCode} onChange={(e) => setVerificationCode(e.target.value.toUpperCase())} placeholder="كودنى كىرگۈزۈڭ" className="w-full p-3 border rounded-xl mb-4 text-center font-mono dark:bg-gray-900 dark:text-white dark:border-gray-700" maxLength={6} />
            <div className="flex gap-3">
              <button onClick={handleVerification} className="flex-1 py-2.5 bg-cyan-600 hover:bg-cyan-700 text-white rounded-lg font-bold transition">تەستىقلاش</button>
              <button onClick={() => setShowSuccessModal(false)} className="flex-1 py-2.5 bg-gray-300 dark:bg-gray-700 text-gray-700 dark:text-white rounded-lg font-medium transition">ياپىمەن</button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}