// src/pages/QuantumProjects.jsx
import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Code, ExternalLink, Terminal, Copy, Check, Clock } from 'lucide-react';
import defaultProjects from '../data/quantumProjects.js';

export default function QuantumProjects({ data }) {
  // تاللانغان تۈرنىڭ كودىنى ئېچىش ھالىتى
  const [activeCodeId, setActiveCodeId] = useState(null);
  const [copiedId, setCopiedId] = useState(null);

  // مەلۇمات شەكلىنى جەزملەش
  let projects = [];
  if (Array.isArray(data) && data.length > 0) {
    projects = data;
  } else if (data && typeof data === 'object') {
    projects = data.projects || Object.values(data);
  }

  // ئەگەر سىرتتىن كەلمىسە كونا ئۆلچەملىك مەلۇماتنى ئىشلىتىش
  const displayProjects = projects.length > 0 ? projects : defaultProjects;

  const toggleCode = (id) => {
    setActiveCodeId(activeCodeId === id ? null : id);
  };

  const copyToClipboard = (id, codeText) => {
    navigator.clipboard.writeText(codeText);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  return (
    <div className="text-right font-['UKIJ_Tuz','Microsoft_Uighur',sans-serif]" dir="rtl">
      {/* باش قىسمى */}
      <div className="mb-8 border-b border-slate-200 dark:border-slate-800 pb-4">
        <h2 className="text-2xl font-black text-emerald-600 dark:text-emerald-400 flex items-center gap-2 justify-start">
          <span>💻</span> ئالىي ئەمەلىي كۋانتۇم تۈرلىرى (Quantum Lab)
        </h2>
        <p className="text-sm text-slate-500 mt-1">
          17 يىللىق پىشقان ئالگورىزىم لايىھەلىرى، IBM Qiskit ۋە TensorFlow Quantum ئەمەلىي كود ئامبىرى.
        </p>
      </div>

      {/* تۈرلەر تىزىملىكى */}
      <div className="grid gap-6 grid-cols-1">
        {displayProjects.map((project, index) => {
          const isCodeOpen = activeCodeId === project.id;
          return (
            <motion.div 
              key={project.id || index}
              layout="position"
              className={`bg-white dark:bg-slate-900 border rounded-3xl overflow-hidden shadow-sm transition-all duration-300 ${
                isCodeOpen ? 'border-emerald-500 ring-4 ring-emerald-500/5' : 'border-slate-200/80 dark:border-slate-800 hover:border-slate-300'
              }`}
            >
              {/* كارتىنىڭ ئاساسىي ئۇچۇرلىرى */}
              <div className="p-6">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                  <div className="flex items-start gap-3.5">
                    <div className="p-3 bg-emerald-50 dark:bg-emerald-950/50 text-emerald-600 dark:text-emerald-400 rounded-2xl shrink-0">
                      <Code className="w-6 h-6" />
                    </div>
                    <div>
                      <h3 className="font-black text-xl text-slate-900 dark:text-white">
                        {project.title || project.name || "قۇرۇلۇش نامسىز"}
                      </h3>
                      <div className="flex items-center gap-3 mt-1.5 font-sans text-xs text-slate-400">
                        <span className="flex items-center gap-1 bg-slate-100 dark:bg-slate-800 px-2.5 py-1 rounded-md text-slate-600 dark:text-slate-300">
                          <Clock className="w-3.5 h-3.5" /> {project.duration || "1 ھەپتە"}
                        </span>
                        <span className="bg-emerald-50 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-400 px-2.5 py-1 rounded-md font-medium">
                          {project.tech || "Qiskit / Python"}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                <p className="text-slate-600 dark:text-slate-300 mt-4 text-base leading-relaxed">
                  {project.description || "بۇ تۈرگە چۈشەندۈرۈش بېرىلمىگەن."}
                </p>
              </div>

              {/* مەشغۇلات ستونى */}
              <div className="p-4 bg-slate-50 dark:bg-slate-900/60 px-6 flex items-center justify-between border-t border-slate-100 dark:border-slate-800">
                <span className="text-xs text-slate-400 font-mono">ID: {project.id || "N/A"}</span>
                
                <button 
                  onClick={() => toggleCode(project.id)}
                  className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-bold transition-all ${
                    isCodeOpen 
                      ? 'bg-slate-900 text-white dark:bg-slate-800' 
                      : 'bg-emerald-50 hover:bg-emerald-100 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-400'
                  }`}
                >
                  <Terminal className="w-4 h-4" />
                  {isCodeOpen ? "كودنى يوشۇرۇش" : "كودنى كۆرۈش"}
                  <ExternalLink className={`w-3.5 h-3.5 transition-transform ${isCodeOpen ? 'rotate-180' : ''}`} />
                </button>
              </div>

              {/* 💻 كارتىنىڭ ئۆز ئىچىدە يۇمشاق ئېچىلىدىغان كود سىناقخانىسى */}
              <AnimatePresence>
                {isCodeOpen && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: "auto" }}
                    exit={{ opacity: 0, height: 0 }}
                    transition={{ duration: 0.3 }}
                    className="bg-slate-950 border-t border-slate-800 overflow-hidden"
                  >
                    <div className="flex items-center justify-between px-5 py-3 bg-slate-900 border-b border-slate-800/60 text-slate-400 text-xs font-mono">
                      <span className="flex items-center gap-2">
                        <span className="w-2.5 h-2.5 bg-rose-500 rounded-full"></span>
                        <span className="w-2.5 h-2.5 bg-amber-500 rounded-full"></span>
                        <span className="w-2.5 h-2.5 bg-emerald-500 rounded-full"></span>
                        <span className="ml-2 text-slate-500">quantum_core.py</span>
                      </span>
                      
                      <button
                        onClick={() => copyToClipboard(project.id, project.code || "# كود تېپىلمىدى")}
                        className="flex items-center gap-1 px-2.5 py-1 bg-slate-800/80 hover:bg-slate-800 rounded-md text-slate-300 hover:text-white transition"
                      >
                        {copiedId === project.id ? (
                          <>
                            <Check className="w-3.5 h-3.5 text-emerald-400" />
                            <span className="text-emerald-400">كۆچۈرۈلدى</span>
                          </>
                        ) : (
                          <>
                            <Copy className="w-3.5 h-3.5" />
                            <span>كۆچۈرۈش</span>
                          </>
                        )}
                      </button>
                    </div>

                    <div className="p-5 font-mono text-xs text-left overflow-x-auto text-emerald-400 bg-slate-950 leading-relaxed" dir="ltr">
                      <pre><code>{project.code || "# بۇ تۈرنىڭ ئەمەلىي كۆدى يۈكلەنمىگەن."}</code></pre>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
}