import { useState, useRef, useEffect } from "react";

// ── Helpers ──────────────────────────────────────────────────────────────────
function generateCertId() {
  const digits = Math.floor(100000 + Math.random() * 900000);
  return `UAA-2026-${digits}`;
}

function getLocalDate() {
  const d = new Date();
  const months = [
    "يانۋار", "فېۋرال", "مارت", "ئاپرىل", "ماي", "ئىيۇن",
    "ئىيۇل", "ئاۋغۇست", "سېنتەبر", "ئۆكتەبر", "نويابر", "دېكابر",
  ];
  return `${d.getFullYear()} - ${months[d.getMonth()]} ${d.getDate()}`;
}

const CERT_META = {
  "رەقەملىك ئاتا-ئانىلىق گۇۋاھنامىسى": {
    en: "Digital Parenting Certificate",
    icon: "👨‍👩‍👧‍👦",
    color: "#22c55e",
    glow: "#16a34a",
    badge: "BRONZE",
  },
  "رەقەملىك ئەخلاق گۇۋاھنامىسى": {
    en: "Digital Ethics Certificate",
    icon: "⚖️",
    color: "#3b82f6",
    glow: "#1d4ed8",
    badge: "SILVER",
  },
  "تور پسىخولوگىيەسى خەۋەردارلىق گۇۋاھنامىسى": {
    en: "Cyber Psychology Awareness Certificate",
    icon: "🧠",
    color: "#6366f1",
    glow: "#4338ca",
    badge: "SILVER",
  },
  "پائالىيەتتىكى ئالاھىدە ئىشتىراك گۇۋاھنامىسى": {
    en: "Distinguished Participation Certificate",
    icon: "🏆",
    color: "#eab308",
    glow: "#ca8a04",
    badge: "GOLD",
  },
};

function saveCertificate(data) {
  try {
    const existing = JSON.parse(localStorage.getItem("uaa_certificates") || "[]");
    existing.push(data);
    localStorage.setItem("uaa_certificates", JSON.stringify(existing));
  } catch (e) {
    console.warn("localStorage unavailable:", e);
  }
}

// ── Neural network SVG background ───────────────────────────────────────────
function NeuralBg({ color }) {
  const nodes = [
    [80, 80], [200, 120], [350, 60], [500, 100], [640, 80],
    [720, 140], [100, 220], [260, 260], [420, 200], [580, 240],
    [680, 280], [140, 380], [300, 340], [460, 380], [620, 360],
    [760, 320], [200, 460], [400, 480], [560, 460], [740, 460],
  ];
  const edges = [
    [0, 1], [1, 2], [2, 3], [3, 4], [4, 5],
    [0, 6], [1, 7], [2, 8], [3, 9], [4, 10],
    [6, 7], [7, 8], [8, 9], [9, 10],
    [6, 11], [7, 12], [8, 13], [9, 14], [10, 15],
    [11, 12], [12, 13], [13, 14], [14, 15],
    [11, 16], [12, 17], [13, 18], [14, 18], [15, 19],
    [16, 17], [17, 18], [18, 19],
  ];
  return (
    <svg className="absolute inset-0 w-full h-full opacity-[0.08]" viewBox="0 0 800 520" preserveAspectRatio="xMidYMid slice">
      {edges.map(([a, b], i) => (
        <line
          key={i}
          x1={nodes[a][0]} y1={nodes[a][1]}
          x2={nodes[b][0]} y2={nodes[b][1]}
          stroke={color} strokeWidth="0.8" strokeOpacity="0.6"
        />
      ))}
      {nodes.map(([x, y], i) => (
        <circle key={i} cx={x} cy={y} r="3" fill={color} fillOpacity="0.5" />
      ))}
    </svg>
  );
}

// ── Uyghur geometric pattern ─────────────────────────────────────────────────
function UyghurPattern({ color }) {
  return (
    <svg className="absolute inset-0 w-full h-full opacity-[0.05]" viewBox="0 0 200 200" preserveAspectRatio="repeat">
      <defs>
        <pattern id="uyghur" x="0" y="0" width="40" height="40" patternUnits="userSpaceOnUse">
          <polygon points="20,2 38,11 38,29 20,38 2,29 2,11" fill="none" stroke={color} strokeWidth="0.6" />
          <polygon points="20,8 32,14 32,26 20,32 8,26 8,14" fill="none" stroke={color} strokeWidth="0.4" />
          <circle cx="20" cy="20" r="3" fill={color} fillOpacity="0.4" />
          <line x1="20" y1="2" x2="20" y2="8" stroke={color} strokeWidth="0.4" />
          <line x1="38" y1="11" x2="32" y2="14" stroke={color} strokeWidth="0.4" />
          <line x1="38" y1="29" x2="32" y2="26" stroke={color} strokeWidth="0.4" />
          <line x1="20" y1="38" x2="20" y2="32" stroke={color} strokeWidth="0.4" />
          <line x1="2" y1="29" x2="8" y2="26" stroke={color} strokeWidth="0.4" />
          <line x1="2" y1="11" x2="8" y2="14" stroke={color} strokeWidth="0.4" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#uyghur)" />
    </svg>
  );
}

// ── Wolf silhouette (Blue Wolf — Uyghur cultural symbol) ────────────────────
function WolfSilhouette({ color }) {
  return (
    <svg className="absolute bottom-6 right-8 opacity-[0.08] h-32 w-32 pointer-events-none" viewBox="0 0 100 100" fill={color}>
      <path d="M15,70 L20,50 L18,35 L25,28 L30,15 L38,25 L45,20 L50,30 L55,20 L62,25 L70,15 L75,28 L82,35 L80,50 L85,70 L75,72 L70,58 L60,65 L50,60 L40,65 L30,58 Z" />
    </svg>
  );
}

// ── Certificate render ────────────────────────────────────────────────────────
function CertificateCard({ name, certType, certId, date, score, certRef }) {
  const meta = CERT_META[certType] || {
    en: certType,
    icon: "🎓",
    color: "#3b82f6",
    glow: "#1d4ed8",
    badge: "CERTIFIED",
  };
  const isGold = meta.badge === "GOLD";

  return (
    <div
      ref={certRef}
      id="certificate-card"
      className="relative overflow-hidden rounded-3xl"
      style={{
        width: "100%",
        maxWidth: "840px",
        minHeight: "580px",
        background: "linear-gradient(135deg, #030a16 0%, #061224 50%, #020710 100%)",
        border: `2px solid ${meta.color}66`,
        boxShadow: `0 0 70px ${meta.glow}44, 0 0 140px ${meta.glow}22, inset 0 1px 0 ${meta.color}33`,
        fontFamily: "'Segoe UI', 'Helvetica Neue', sans-serif",
      }}
    >
      {/* Background layers */}
      <UyghurPattern color={meta.color} />
      <NeuralBg color={meta.color} />
      <WolfSilhouette color={meta.color} />

      {/* Top accent bar */}
      <div className="absolute top-0 left-0 right-0 h-2 rounded-t-3xl"
        style={{ background: `linear-gradient(90deg, transparent, ${meta.color}, ${isGold ? "#fbbf24" : meta.color}, transparent)` }} />

      {/* Corner ornaments */}
      {[["top-4 left-4", ""], ["top-4 right-4", "scale-x-[-1]"], ["bottom-4 left-4", "scale-y-[-1]"], ["bottom-4 right-4", "scale-[-1]"]].map(([pos, tr], i) => (
        <div key={i} className={`absolute ${pos} w-10 h-10 opacity-40`} style={{ transform: tr || undefined }}>
          <svg viewBox="0 0 32 32" fill="none">
            <path d="M2,2 L2,18 M2,2 L18,2" stroke={meta.color} strokeWidth="2.5" strokeLinecap="round" />
            <circle cx="2" cy="2" r="2.5" fill={meta.color} />
          </svg>
        </div>
      ))}

      <div className="relative z-10 p-8 sm:p-14 flex flex-col items-center text-center">
        {/* Academy header */}
        <div className="flex items-center gap-4 mb-5">
          <div className="w-16 h-px opacity-30" style={{ background: meta.color }} />
          <div>
            <div className="text-sm tracking-[0.3em] uppercase font-black" style={{ color: meta.color }}>
              Uyghur AI Academy
            </div>
            <div className="text-xs text-blue-200/40 tracking-widest mt-0.5" style={{ direction: "rtl" }}>
              ئۇيغۇر سۈنئىي ئىدراك ئاكادېمىيىسى
            </div>
          </div>
          <div className="w-16 h-px opacity-30" style={{ background: meta.color }} />
        </div>

        {/* Badge tier */}
        <div className="inline-flex items-center gap-2 rounded-full px-5 py-1.5 mb-5 text-xs font-black tracking-widest uppercase"
          style={{ border: `1px solid ${meta.color}66`, background: `${meta.color}20`, color: meta.color }}>
          <span>{meta.icon}</span>
          <span>{meta.badge} VERIFIED</span>
          <span>{meta.icon}</span>
        </div>

        {/* "This certifies" */}
        <p className="text-blue-200/50 text-[10px] tracking-widest uppercase">International Digital Credentials</p>
        <p className="text-blue-200/70 text-xs mt-1 mb-1" style={{ direction: "rtl" }}>مەزكۇر شەرەپلىك گۇۋاھنامە تولۇق باھالاشتىن ئۆتكەن تۆۋەندىكى شەخسكە تاپشۇرۇلىدۇ:</p>

        {/* Name */}
        <div className="my-4 relative w-full max-w-md">
          <div className="absolute left-0 right-0 top-1/2 h-px opacity-15"
            style={{ background: `linear-gradient(90deg, transparent, ${meta.color}, transparent)`, transform: "translateY(-50%)" }} />
          <h2 className="text-3xl sm:text-4xl font-black tracking-wide relative px-6 z-10 inline-block bg-[#051020]/90 rounded-xl"
            style={{ color: isGold ? "#fbbf24" : meta.color, textShadow: `0 0 35px ${meta.glow}aa` }}>
            {name || "— — —"}
          </h2>
        </div>

        {/* Certificate type */}
        <div className="mb-2">
          <p className="text-blue-200/50 text-[11px] mb-1 uppercase tracking-widest">for outstanding mastery and completion of</p>
          <h3 className="text-xl sm:text-2xl font-black text-white tracking-wide mb-1">
            {meta.en}
          </h3>
          <h4 className="text-lg font-black mb-1.5" style={{ color: meta.color, direction: "rtl" }}>
            {certType}
          </h4>
          <p className="text-blue-200/60 text-xs max-w-xl mx-auto leading-relaxed" style={{ direction: "rtl" }}>
            «سىبېر پسىخولوگىيە ۋە ئۇيغۇر ئائىلىلىرىنىڭ رەقەملىك كەلگۈسى» ئوقۇش پىلانىنىڭ بارلىق تەلىپىنى، تېخنىكىلىق تەجرىبە ۋە ئىجتىمائىي ئەخلاق ئۆلچەملىرىنى يۇقىرى نەتىجىدە تولۇقلىغانلىقى ئۈچۈن بېرىلدى.
          </p>
        </div>

        {/* Score bar */}
        <div className="mt-4 mb-6 w-full max-w-xs bg-slate-950/50 p-3 rounded-xl border border-white/5">
          <div className="flex justify-between text-xs mb-1" style={{ direction: "rtl" }}>
            <span className="text-blue-200/40">ئاكادېمىك باھالاش نەتىجىسى</span>
            <span style={{ color: meta.color }} className="font-bold">{score}%</span>
          </div>
          <div className="h-2 rounded-full bg-white/10 overflow-hidden">
            <div className="h-full rounded-full" style={{
              width: `${score}%`,
              background: `linear-gradient(90deg, ${meta.glow}, ${meta.color})`,
              transition: "width 1s ease",
            }} />
          </div>
        </div>

        {/* Meta row */}
        <div className="flex items-center justify-center gap-8 flex-wrap border-t border-white/10 pt-4 w-full text-slate-300">
          <div className="text-center">
            <div className="text-blue-200/30 text-[10px] mb-0.5 uppercase tracking-widest">Verification ID</div>
            <div className="font-mono text-xs font-black" style={{ color: meta.color }}>{certId}</div>
          </div>
          <div className="w-px h-6 bg-white/10" />
          <div className="text-center">
            <div className="text-blue-200/30 text-[10px] mb-0.5 uppercase tracking-widest">Issue Date</div>
            <div className="text-white text-xs font-bold" style={{ direction: "rtl" }}>{date}</div>
          </div>
          <div className="w-px h-6 bg-white/10" />
          <div className="text-center">
            <div className="text-blue-200/30 text-[10px] mb-0.5 uppercase tracking-widest">Authority</div>
            <div className="text-white text-xs font-bold font-sans">Global UAA Council</div>
          </div>
        </div>

        {/* ⚖️ پائالىيەت يۆتەكچى رەھبەرلىك ھەيئىتى ئىمزاسى ───────────────── */}
        <div className="mt-8 grid grid-cols-3 gap-4 w-full border-t border-white/5 pt-4">
          <div className="text-center flex flex-col items-center justify-end">
            <div className="font-mono text-xs italic text-blue-300/70 mb-1 tracking-wider h-6 flex items-center justify-center">Kawuljan A.</div>
            <div className="w-24 h-px bg-white/20 mb-1" />
            <div className="text-white font-bold text-[11px]" style={{ direction: "rtl" }}>قاۋۇلجان ئابدۇرېھىم</div>
            <div className="text-blue-200/40 text-[10px] mt-0.5" style={{ direction: "rtl" }}>دىرېكتور پىلانلىغۇچى</div>
          </div>
          
          <div className="text-center flex flex-col items-center justify-end">
            <div className="font-mono text-xs italic text-green-400/70 mb-1 tracking-wider h-6 flex items-center justify-center">Zakiya O.</div>
            <div className="w-24 h-px bg-white/20 mb-1" />
            <div className="text-white font-bold text-[11px]" style={{ direction: "rtl" }}>زەكىيە ئوبۇل</div>
            <div className="text-blue-200/40 text-[10px] mt-0.5" style={{ direction: "rtl" }}>كورس يېتەكچىسى</div>
          </div>

          <div className="text-center flex flex-col items-center justify-end">
            <div className="font-mono text-[10px] italic text-amber-400/70 mb-1 leading-none h-6 flex flex-col items-center justify-center">
              <span>Alim / Elnur</span>
            </div>
            <div className="w-24 h-px bg-white/20 mb-1" />
            <div className="text-white font-bold text-[11px]" style={{ direction: "rtl" }}>ئالىم ، ئەلنۇر</div>
            <div className="text-blue-200/40 text-[10px] mt-0.5" style={{ direction: "rtl" }}>مۇتەخەسسىس تەتقىقاتچى</div>
          </div>
        </div>
      </div>

      {/* Bottom accent */}
      <div className="absolute bottom-0 left-0 right-0 h-1.5 rounded-b-3xl"
        style={{ background: `linear-gradient(90deg, transparent, ${meta.color}, transparent)` }} />
    </div>
  );
}

// ── Main Page ─────────────────────────────────────────────────────────────────
export default function Certificate() {
  const params = new URLSearchParams(window.location.search);
  const initCertType = params.get("certType") || "رەقەملىك ئاتا-ئانىلىق گۇۋاھنامىسى";
  const initScore = parseInt(params.get("score") || "0", 10);

  const [name, setName] = useState("");
  const [certType, setCertType] = useState(initCertType);
  const [score] = useState(initScore);
  const [certId] = useState(generateCertId);
  const [date] = useState(getLocalDate);
  const [saved, setSaved] = useState(false);
  const [generating, setGenerating] = useState(false);
  const certRef = useRef(null);

  const meta = CERT_META[certType] || { color: "#3b82f6", en: certType, icon: "🎓" };

  useEffect(() => {
    if (name.trim().length > 0 && !saved) {
      const timeout = setTimeout(() => {
        const record = { id: Date.now().toString(), name, certType, score, date, certId };
        saveCertificate(record);
        setSaved(true);
      }, 1500);
      return () => clearTimeout(timeout);
    }
  }, [name, certType, certId, date, score, saved]);

  const handleDownloadPNG = async () => {
    setGenerating(true);
    try {
      const { default: html2canvas } = await import("https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.esm.js");
      const canvas = await html2canvas(certRef.current, { scale: 2, backgroundColor: null, useCORS: true });
      const link = document.createElement("a");
      link.download = `UAA-Certificate-${certId}.png`;
      link.href = canvas.toDataURL("image/png");
      link.click();
    } catch (e) {
      alert("PNG چۈشۈرۈشتە خاتالىق كۆرۈلدى. تور ئۇلانغانلىقىنى تەكشۈرۈڭ.");
    } finally {
      setGenerating(false);
    }
  };

  const handlePrint = () => window.print();

  const allCertTypes = Object.keys(CERT_META);

  return (
    <div className="min-h-screen text-white py-10 px-4" style={{
      background: "linear-gradient(135deg, #050d1a 0%, #0a1628 50%, #061022 100%)",
      fontFamily: "'Segoe UI', 'Helvetica Neue', sans-serif",
    }}>
      {/* Ambient */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden">
        <div className="absolute top-10 left-1/3 w-80 h-80 rounded-full opacity-10" style={{ background: `radial-gradient(circle, ${meta.color}, transparent)`, filter: "blur(80px)" }} />
      </div>

      <div className="max-w-5xl mx-auto relative z-10">
        {/* Header */}
        <div className="text-center mb-10">
          <div className="inline-flex items-center gap-2 bg-white/5 border border-yellow-400/30 rounded-full px-4 py-1.5 mb-5">
            <span className="text-yellow-400">⬡</span>
            <span className="text-yellow-300 text-xs font-semibold tracking-widest uppercase">Uyghur AI Academy</span>
            <span className="text-yellow-400">⬡</span>
          </div>
          <h1 className="text-2xl sm:text-3xl font-black text-white mb-2" style={{ direction: "rtl" }}>
            خەلقئارالىق ئاكادېمىك گۇۋاھنامە سىستېمىسى
          </h1>
          <p className="text-blue-200/50 text-sm" style={{ direction: "rtl" }}>
            تولۇق ئىسمىڭىزنى كىرگۈزۈپ، رەسمىي دەلىللەنگەن گۇۋاھنامىڭىزنى چۈشۈرۈڭ.
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
          {/* Form panel */}
          <div className="lg:col-span-1 space-y-5">
            <div className="bg-white/5 border border-white/10 rounded-2xl p-6 backdrop-blur-md">
              <h2 className="text-sm font-bold text-white mb-4 text-right" style={{ direction: "rtl" }}>
                📋 گۇۋاھنامە ئۇچۇر تەڭشەكلىرى
              </h2>

              {/* Name input */}
              <div className="mb-4">
                <label className="block text-blue-200/70 text-xs mb-1.5 text-right" style={{ direction: "rtl" }}>
                  تولۇق ئىسمىڭىز <span className="text-red-400">*</span>
                </label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => { setName(e.target.value); setSaved(false); }}
                  placeholder="ئىسمىڭىزنى كىرگۈزۈڭ"
                  className="w-full bg-white/5 border border-white/20 rounded-xl px-4 py-3 text-white text-sm text-right placeholder:text-white/30 focus:outline-none focus:border-blue-400/60 transition-all"
                  style={{ direction: "rtl" }}
                />
              </div>

              {/* Cert type */}
              <div className="mb-4">
                <label className="block text-blue-200/70 text-xs mb-1.5 text-right" style={{ direction: "rtl" }}>
                  گۇۋاھنامە تۈرىنى تاللاڭ
                </label>
                <select
                  value={certType}
                  onChange={(e) => setCertType(e.target.value)}
                  className="w-full bg-slate-800 border border-white/20 rounded-xl px-4 py-3 text-white text-xs text-right focus:outline-none focus:border-blue-400/60 transition-all"
                  style={{ direction: "rtl" }}
                >
                  {allCertTypes.map((ct) => (
                    <option key={ct} value={ct}>{ct}</option>
                  ))}
                </select>
              </div>

              {/* Auto fields */}
              <div className="space-y-3">
                {[
                  { label: "رەسمىي گۇۋاھنامە نومۇرى", val: certId, mono: true },
                  { label: "باھالانغان چېسلا", val: date },
                  { label: "ئومۇمىي نەتىجە", val: `${score}%` },
                ].map(({ label, val, mono }) => (
                  <div key={label} className="bg-white/5 rounded-xl px-4 py-3 border border-white/5">
                    <div className="text-blue-200/50 text-xs mb-0.5 text-right" style={{ direction: "rtl" }}>{label}</div>
                    <div className={`text-white text-sm text-right ${mono ? "font-mono font-bold text-yellow-400" : "font-semibold"}`} style={{ direction: "rtl" }}>{val}</div>
                  </div>
                ))}
              </div>

              {/* Saved indicator */}
              {saved && name.trim() && (
                <div className="mt-3 text-center text-green-400 text-xs font-bold animate-pulse" style={{ direction: "rtl" }}>
                  ✓ سىستېمىغا مۇۋەپپەقىيەتلىك تىزىملاندى
                </div>
              )}
            </div>

            {/* Download buttons */}
            <div className="space-y-2">
              <button
                onClick={handleDownloadPNG}
                disabled={!name.trim() || generating}
                className="w-full py-4 rounded-xl font-black text-sm transition-all duration-200 hover:scale-[102%] disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:scale-100 flex items-center justify-center gap-2 shadow-lg"
                style={{
                  background: name.trim() ? `linear-gradient(135deg, ${meta.glow}, ${meta.color})` : "#1e2a3a",
                  boxShadow: name.trim() ? `0 4px 20px ${meta.color}44` : "none",
                }}
              >
                {generating ? "⏳ كاپسۇل رەسىم ھاسىللىنىۋاتىدۇ..." : "⬇️ خەلقئارالىق PNG چۈشۈرۈش"}
              </button>

              <button
                onClick={handlePrint}
                disabled={!name.trim()}
                className="w-full py-3.5 rounded-xl font-bold text-sm transition-all duration-200 hover:scale-[102%] disabled:opacity-40 disabled:cursor-not-allowed border border-white/20 bg-white/5 hover:bg-white/10"
                style={{ direction: "rtl" }}
              >
                🖨️&nbsp; باسما نۇسخىنى بېسىپ چىقىرىش (PDF)
              </button>

              <button
                onClick={() => window.history.back()}
                className="w-full py-3 rounded-xl text-sm text-blue-200/60 hover:text-blue-200 transition-all border border-white/10 hover:border-white/20"
                style={{ direction: "rtl" }}
              >
                ← ئاكادېمىيە باش بېتىگە قايتىش
              </button>
            </div>
          </div>

          {/* Certificate preview */}
          <div className="lg:col-span-2 overflow-x-auto pb-4">
            <div className="text-right text-xs text-blue-200/40 mb-2 font-bold" style={{ direction: "rtl" }}>
              گۇۋاھنامە نەق مەيدان كۆرۈنۈشى (HD Preview)
            </div>
            <div className="min-w-[760px] lg:min-w-0">
              <CertificateCard
                name={name || "ئىسمىڭىزنى كىرگۈزۈڭ"}
                certType={certType}
                certId={certId}
                date={date}
                score={score}
                certRef={certRef}
              />
            </div>
          </div>
        </div>
      </div>

      {/* Print styles */}
      <style>{`
        @media print {
          body > * { display: none !important; }
          #certificate-card { display: block !important; position: fixed !important; top: 0; left: 0; width: 100vw !important; height: 100vh !important; max-width: none !important; border-radius: 0 !important; border: none !important; }
        }
      `}</style>
    </div>
  );
}