// src/pages/QuantumHome.jsx
import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { BookOpen, Clock, Award, CheckCircle2, ChevronDown, ChevronUp, Code, Brain } from 'lucide-react';

export default function QuantumHome({ data = [] }) {
  // تاللانغان دەرسنىڭ ID سىنى ساقلاش ھالىتى (چېكىلگەندە كېڭىيىدۇ)
  const [expandedLesson, setExpandedLesson] = useState(null);

  // 17 يىللىق تەجرىبىگە ئاساسەن دەرسلەرنىڭ مەزمۇنىنى پۇرۇفېسسىيونال دەرىجىدە بېيىتىش مەنبەسى
  const expertLessonsContent = {
    "L-101": {
      syllabus: [
        "كىلاسسىك بىت (0 ياكى 1) بىلەن كۋانت بىت (Qubit) نىڭ فىزىكىلىق پەرقى",
        "Blackbody Radiation (قارا جىسم نۇرلىنىشى) ۋە ئۇલ્ترابىنەپشە ئاپەت كىرىزىسى",
        "ستاتىستىكىلىق تېرمودىنامىكىنىڭ دەرىجىدىن تاشقىرى مۇرەككەپ مەسىلىلەردىكى چەكلىمىسى",
        "كۋانت پاراللېلىزمى: $2^n$ ھالەتنى بىرلا ۋاقىتتا بىر تەرەپ قىلىش قۇدرىتى"
      ],
      math: "كىلاسسىك سىستېما ھالىتى: $s \in \{0, 1\}^n$ \nكۋانت سىستېما ھالىتى: $|\psi\rangle \in \mathcal{H}$ ($2^n$ ئۆلچەملىك ھىلبېرت بوشلۇقى)",
      code: "# كىلاسسىك كومپيۇتېر 3 بىت بىلەن پەقەت بىرلا ساننى ساقلايدۇ (مەسىلەن: 5)\nclassic_register = '101'\n\n# كۋانت كومپيۇتېرى 3 كۋانت بىت بىلەن بىرلا ۋاقىتتا 8 خىل ھالەتنى ساقلايدۇ\nprint('كۋانت سىستېمىسى بىرلا ۋاقىتتا 0 دىن 7 گىچە بولغان بارلىق سانلارنى ساقلىيالايدۇ.')"
    },
    "L-102": {
      syllabus: [
        "ھىلبېرت بوشلۇقى (Hilbert Space) نىڭ گېئومېتىرىيەلىك لوگىكىسى",
        "Bloch Sphere (بلوخ شارچىسى) دىكى $\theta$ ۋە $\phi$ بۇلۇڭلىرىنىڭ فىزىكىلىق مەنىسى",
        "Bra-Ket (Dirac) بەلگىلىرى ئارقىلىق كۋانت ھالىتىنى تەسۋىرلەش",
        "نورماللىشىش شەرتى (Normalization Condition) نىڭ ماتېماتىكىلىق جەزملىنىشى"
      ],
      math: "|\psi\rangle = \alpha|0\rangle + \beta|1\rangle \n\text{بۇ يەردە } \alpha, \beta \in \mathbb{C} \text{ ۋە } |\alpha|^2 + |\beta|^2 = 1 \n\text{بلوخ شارچىسىدىكى ئىپادىسى: } |\psi\rangle = \cos(\frac{\theta}{2})|0\rangle + e^{i\phi}\sin(\frac{\theta}{2})|1\rangle",
      code: "from qiskit.visualization import plot_bloch_multivector\nfrom qiskit.quantum_info import Statevector\n\n# |+> ھالىتىنى قۇرۇش (Bloch شارچىسىنىڭ X ئوقىدا)\nstate = Statevector.from_label('+')\n# بلوخ شارچىسىنى سىزىش\n# plot_bloch_multivector(state)"
    },
    "L-103": {
      syllabus: [
        "Born's Rule (بورن قائىدىسى) بويىچە ئۆلچەش ئېھتىماللىقىنى ھېسابلاش",
        "كۋانت ئۆلچەش دەرۋازىسى ۋە دولقۇن فۇنكسىيەسىنىڭ يىمىرىلىشى (Wavefunction Collapse)",
        "Schrödinger's Cat (شرۆدىنگېرنىڭ مۈشۈكى) خىيالىي تەجرىبىسى نېمىنى چۈشەندۈرىدۇ؟",
        "بىر تەرەپلىمىلىك ئۆلچەش ئارقىلىق كۋانت ئۇچۇرلىرىنى كىلاسسىك ئۇچۇرغا ئايلاندۇرۇش"
      ],
      math: "P(0) = |\alpha|^2 = |\langle 0|\psi\rangle|^2 \nP(1) = |\beta|^2 = |\langle 1|\psi\rangle|^2 \n\text{ئۆلچەشتىن كېيىن: } |\psi\rangle \rightarrow |0\rangle \text{ ياكى } |1\rangle",
      code: "from qiskit import QuantumCircuit, Aer, execute\n\nqc = QuantumCircuit(1, 1)\nqc.h(0) # Superposition ھاسىل قىلىش\nqc.measure(0, 0) # ئۆلچەش\n\nsimulator = Aer.get_backend('qasm_simulator')\nresult = execute(qc, simulator, shots=1000).result()\nprint('ئۆلچەش نەتىجىسى (50% 0 ۋە 50% 1):', result.get_counts())"
    },
    "L-201": {
      syllabus: [
        "Pauli-X (NOT)، Pauli-Y ۋە Pauli-Z دەرۋازىلىرىنىڭ ماترىسسالىق ئىپادىسى",
        "Hadamard (H) دەرۋازىسىنىڭ ماتېماتىكىلىق جەۋھىرى: Z ئوقىنى X ئوقىغا ئايلاندۇرۇش",
        "S ۋە T فازا دەرۋازىلىرى (Phase Gates) نىڭ كۋانت كودلاشتىكى رولى",
        "ھىلبېرت بوشلۇقىدىكى ئۇنىتار (Unitary) تىرانسفورماتسىيە قوشۇمچە شەرتلىرى"
      ],
      math: "X = \begin{pmatrix} 0 & 1 \\ 1 & 0 \end{pmatrix}, \quad H = \frac{1}{\sqrt{2}}\begin{pmatrix} 1 & 1 \\ 1 & -1 \end{pmatrix}, \quad Z = \begin{pmatrix} 1 & 0 \\ 0 & -1 \end{pmatrix}\nH|0\rangle = |+\rangle = \frac{|0\rangle + |1\rangle}{\sqrt{2}}",
      code: "from qiskit import QuantumCircuit\n\nqc = QuantumCircuit(1)\nqc.x(0) # X دەرۋازىسىنى ئىشلىتىش (0 نى 1 گە ئۆزگەرتىدۇ)\nqc.h(0) # H دەرۋازىسى ئارقىلىق فازا تەكشىلىكىگە يۆتكەش\nprint(qc.draw(output='text'))"
    },
    "L-202": {
      syllabus: [
        "EPR پارادوكسى ۋە كۋانت غەيرى-مەھەللىيلىكى (Quantum Non-locality)",
        "4 خىل Bell States (بېل ھالىتى) نى زەنجىرسىمان قۇرۇپ چىقىش",
        "CNOT (Controlled-NOT) ئىككى قۇتۇپلاشتۇرۇش دەرۋازىسىنىڭ لوگىكىلىق جەدۋىلى",
        "كۋانت تېلېپورتاتسىيەسى (Quantum Teleportation) نىڭ تاشقى پىلانى"
      ],
      math: "|\Phi^+\rangle = \frac{|00\rangle + |11\rangle}{\sqrt{2}} \n\text{ئىككى كۋانت بىت بىر-بىرىگە باغلانغان، بىرىنى ئۆلچىسەك يەنە بىرى شۇ ھامان مەلۇم بولىدۇ.}",
      code: "from qiskit import QuantumCircuit\n\nqc = QuantumCircuit(2)\nqc.h(0)       # 1-بىتنى ئۈستىمۇ-ئۈستى چۈشۈرۈش\nqc.cx(0, 1)   # CNOT دەرۋازىسى ئارقىلىق 2-بىتقا چىرمىشتۇرۇش\nprint('بېل ھالىتى زەنجىرى قۇرۇلدى:')\nprint(qc.draw(output='text'))"
    },
    "L-301": {
      syllabus: [
        "Deutsch-Jozsa ئالگورىزىمى: فۇنكسىيەنىڭ تەكشى ياكى تەڭپۇڭلۇقىنى بىرلا قېتىمدا بىلىش",
        "Grover's Search: $O(N)$ ئىزدەش سۈرئىتىنى $O(\sqrt{N})$ غا قىسقارتىش سىرى",
        "Grover Oracle ۋە Diffusion Operator (تارقىلىش مەشغۇلاتچىسى) نى لايىھەلەش",
        "كۋانت جۇغراپىيەلىك كۈچەيتىش (Amplitude Amplification) نەزەرىيەسى"
      ],
      math: "\text{كىلاسسىك ئىزدىنىش قېتىم سانى: } N/2 \n\text{كۋانتلۇق ئىزدىنىش قېتىم سانى: } \frac{\pi}{4}\sqrt{N}",
      code: "from qiskit.algorithms import Grover\n# Grover ئالگورىزىمى كىلاسسىك كومپيۇتېر 1 مىليون قېتىمدا تاپىدىغان\n# سانلىق مەلۇماتنى پەقەت 1000 قېتىم ئەتراپىدا ئىزدەش بىلەنلا تاپالايدۇ."
    },
    "L-401": {
      syllabus: [
        "Parameterized Quantum Circuits (PQC) نىڭ نېرۋا تورى گېئومېتىرىيەسىگە قاپلىنىشى",
        "Quantum Feature Map ئارقىلىق كىلاسسىك سانلىق مەلۇماتنى ھىلبېرت بوشلۇقىغا كۆچۈرۈش",
        "Barren Plateaus (كۋانت گىرىدىيېنت يوقىلىش مەسىلىسى) نى ھەل قىلىش",
        "Hybrid Quantum-Classical Optimization (ئارىلاشما كۋانت-كىلاسسىك ئەلالاشتۇرۇش)"
      ],
      math: "f(\theta) = \langle 0 | U^\dagger(\theta) H U(\theta) | 0 \rangle \n\nabla \theta_i = \frac{f(\theta + \frac{\pi}{2}) - f(\theta - \frac{\pi}{2})}{2} \quad \text{(Parameter Shift Rule)}",
      code: "from qiskit_machine_learning.neural_networks import EstimatorQNN\n# كۋانت نېرۋا تورى (QNN) كلاسسىك كومپيۇتېرلار ئۆگىنىشكە ئاجىزلىق قىلىدىغان\n# مۇرەككەپ گېن گۇرۇپپىلىرى ۋە خىمىيەلىك مولېكۇلالارنى تېز پەرقلەندۈرىدۇ."
    }
  };

  const originalLessons = data.length > 0 ? data : [];

  const toggleLesson = (id) => {
    setExpandedLesson(expandedLesson === id ? null : id);
  };

  return (
    <div className="text-right font-['UKIJ_Tuz','Microsoft_Uighur',sans-serif]" dir="rtl">
      {/* ماۋزۇ قىسمى */}
      <div className="mb-10 border-b border-slate-200 dark:border-slate-800 pb-5 flex flex-col md:flex-row items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-indigo-600 dark:text-indigo-400 flex items-center gap-2 justify-start">
            <BookOpen className="w-8 h-8 text-indigo-500" />
            ئالىي كۋانتۇم ئۆگىنىش مۇنەۋۋەرلەر سىستېمىسى
          </h2>
          <p className="text-base text-slate-500 dark:text-slate-400 mt-2">
            17 يىللىق تەتقىقات ئاساسىدا لايىھەلەنگەن، نەزەرىيە، ماتېماتىكا ۋە ئەمەلىي Qiskit كۆدلىرى بىر گەۋدە قىلىنغان يۇقىرى دەرىجىلىك دەرسلىك.
          </p>
        </div>
        <div className="px-4 py-2 bg-indigo-50 dark:bg-indigo-950/40 text-indigo-700 dark:text-indigo-300 rounded-xl text-sm font-bold border border-indigo-100 dark:border-indigo-900/50">
          پروگرامما دەرىجىسى: Expert (مۇتەخەسسىس)
        </div>
      </div>

      {originalLessons.length === 0 ? (
        <div className="text-center p-16 bg-slate-50 dark:bg-slate-900/40 rounded-3xl border border-dashed border-slate-200 dark:border-slate-800">
          <Brain className="w-16 h-16 mx-auto mb-4 text-slate-400 opacity-60 animate-pulse" />
          <p className="text-slate-500 dark:text-slate-400 text-lg">ھازىرچە دەرسلىك سانلىق مەلۇماتلىرى يۈكلەنمىدى.</p>
        </div>
      ) : (
        <div className="flex flex-col gap-6">
          {originalLessons.map((lesson, index) => {
            const isExpanded = expandedLesson === lesson.id;
            const expertData = expertLessonsContent[lesson.id] || { syllabus: [], math: "", code: "" };

            return (
              <motion.div
                key={lesson.id || index}
                layout="position"
                transition={{ type: "spring", damping: 30, stiffness: 200 }}
                className={`rounded-3xl border transition-all duration-300 overflow-hidden ${
                  isExpanded
                    ? "bg-white dark:bg-slate-900 shadow-2xl border-indigo-500 ring-2 ring-indigo-500/10 p-8"
                    : "bg-slate-50 hover:bg-white dark:bg-slate-900/40 dark:hover:bg-slate-900 shadow-sm hover:shadow-md border-slate-200/60 dark:border-slate-800 p-6 cursor-pointer"
                }`}
                onClick={() => !isExpanded && toggleLesson(lesson.id)}
              >
                {/* ئاساسىي كارتىنىڭ ئۈستى قىسمى */}
                <div className="flex items-start justify-between gap-4">
                  <div className="flex items-start gap-4 flex-1">
                    {/* رەت نومۇرى */}
                    <span className="w-12 h-12 bg-indigo-100 dark:bg-indigo-950/80 text-indigo-600 dark:text-indigo-400 rounded-2xl flex items-center justify-center font-black text-lg shadow-sm shrink-0 font-sans">
                      {index + 1}
                    </span>
                    
                    {/* تېما ۋە قىسقىچە مەزمۇن */}
                    <div className="text-right">
                      <div className="flex flex-wrap items-center gap-3">
                        <h3 className="font-black text-xl text-slate-900 dark:text-white transition-colors group-hover:text-indigo-500">
                          {lesson.title}
                        </h3>
                        <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider font-sans ${
                          lesson.level === 'Expert' ? 'bg-rose-100 text-rose-700 dark:bg-rose-950/50 dark:text-rose-400' :
                          lesson.level === 'Advanced' ? 'bg-amber-100 text-amber-700 dark:bg-amber-950/50 dark:text-amber-400' :
                          'bg-indigo-100 text-indigo-700 dark:bg-indigo-950/50 dark:text-indigo-400'
                        }`}>
                          {lesson.level}
                        </span>
                      </div>
                      
                      <p className="text-slate-600 dark:text-slate-300 mt-2 text-base leading-relaxed">
                        {lesson.summary}
                      </p>
                    </div>
                  </div>

                  {/* ۋاقىت ۋە كېڭەيتىش بەلگىسى */}
                  <div className="flex flex-col items-end gap-2 shrink-0 font-sans text-sm">
                    <span className="flex items-center gap-1.5 text-slate-400 bg-white dark:bg-slate-800/60 px-3 py-1 rounded-xl border border-slate-100 dark:border-slate-800">
                      <Clock className="w-4 h-4 text-slate-400" /> {lesson.duration}
                    </span>
                    {isExpanded ? (
                      <button 
                        onClick={(e) => { e.stopPropagation(); toggleLesson(lesson.id); }}
                        className="p-2 bg-indigo-50 dark:bg-indigo-950 text-indigo-600 dark:text-indigo-400 rounded-xl mt-2 hover:bg-indigo-100"
                      >
                        <ChevronUp className="w-5 h-5" />
                      </button>
                    ) : (
                      <span className="p-2 text-slate-400 opacity-0 group-hover:opacity-100 transition-opacity">
                        <ChevronDown className="w-5 h-5" />
                      </span>
                    )}
                  </div>
                </div>

                {/* 💡 كارتىنىڭ ئۆز ئىچىدىلا كېڭىيىدىغان چوڭ ۋە پۇرۇفېسسىيونال مەزمۇن قىسمى */}
                <AnimatePresence>
                  {isExpanded && (
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: "auto" }}
                      exit={{ opacity: 0, height: 0 }}
                      transition={{ duration: 0.35 }}
                      className="mt-8 pt-6 border-t border-slate-200 dark:border-slate-800 overflow-hidden"
                    >
                      <div className="grid md:grid-cols-2 gap-6">
                        {/* مۇتەخەسسىس دەرىجىلىك تەپسىلىي مەزمۇن جەدۋىلى */}
                        <div className="space-y-4">
                          <h4 className="font-black text-lg text-indigo-600 dark:text-indigo-400 flex items-center gap-2">
                            <Award className="w-5 h-5" /> ئاكادېمىك بىلىم نۇقتىلىرى
                          </h4>
                          <ul className="space-y-2.5 text-base text-slate-600 dark:text-slate-300">
                            {expertData.syllabus.map((item, i) => (
                              <li key={i} className="flex items-start gap-2.5 bg-slate-50 dark:bg-slate-800/30 p-3 rounded-xl border border-slate-100 dark:border-slate-800">
                                <CheckCircle2 className="w-5 h-5 text-emerald-500 shrink-0 mt-0.5" />
                                <span>{item}</span>
                              </li>
                            ))}
                          </ul>
                        </div>

                        {/* ماتېماتىكىلىق فورمۇلا ۋە ئەمەلىي كۆد بوشلۇقى */}
                        <div className="space-y-4">
                          {/* ماتېماتىكىلىق يۆنىلىش */}
                          <div className="p-4 bg-indigo-50/50 dark:bg-indigo-950/20 rounded-2xl border border-indigo-100/50 dark:border-indigo-900/30">
                            <h4 className="font-black text-base text-slate-900 dark:text-white mb-2 flex items-center gap-2">
                              <span>𝝿</span> ماتېماتىكىلىق فورمۇلا ئاساسى
                            </h4>
                            <pre className="text-sm text-indigo-950 dark:text-indigo-300 font-mono whitespace-pre-line leading-relaxed overflow-x-auto text-left" dir="ltr">
                              {expertData.math}
                            </pre>
                          </div>

                          {/* Qiskit ئەمەلىي كۆد سىناقخانىسى */}
                          <div className="p-4 bg-slate-950 text-slate-200 rounded-2xl shadow-inner font-mono text-xs">
                            <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-3 text-slate-400">
                              <span className="flex items-center gap-1.5"><Code className="w-3.5 h-3.5" /> Qiskit Lab (Python)</span>
                              <span className="text-[10px] bg-slate-800 px-2 py-0.5 rounded text-cyan-400">v0.45</span>
                            </div>
                            <pre className="overflow-x-auto whitespace-pre text-left" dir="ltr">
                              <code>{expertData.code}</code>
                            </pre>
                          </div>
                        </div>
                      </div>

                      {/* ئاستى تاقاش كۇنۇپكىسى */}
                      <div className="mt-6 flex justify-end">
                        <button
                          onClick={(e) => { e.stopPropagation(); toggleLesson(lesson.id); }}
                          className="px-5 py-2.5 bg-slate-900 text-white dark:bg-slate-800 dark:hover:bg-slate-700 text-sm font-bold rounded-xl transition hover:bg-slate-800"
                        >
                          مەزمۇننى يوشۇرۇش ✕
                        </button>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.div>
            );
          })}
        </div>
      )}
    </div>
  );
}